Color groupColorFromValue(Object? value) {
  if (value is int) return Color(value);
  if (value is String) {
    final parsed = int.tryParse(value);
    if (parsed != null) return Color(parsed);
  }
  return ssOrange;
}

String normalizarEmojiReaccion(String emoji) {
  final trimmed = emoji.trim();
  if (trimmed.isEmpty) return '';
  final first = trimmed.characters.first;
  return kSundayReactionEmojis.contains(first) ? first : '';
}

Map<String, bool> resolvedNotificationSettings(Map<String, dynamic>? userData) {
  final rawSettings = userData?['notificationSettings'];
  final settings = <String, bool>{...kDefaultNotificationSettings};

  if (rawSettings is Map) {
    for (final entry in kDefaultNotificationSettings.entries) {
      final value = rawSettings[entry.key];
      if (value is bool) {
        settings[entry.key] = value;
      }
    }
  }

  return settings;
}

bool notificationGlobalEnabledFromData(Map<String, dynamic>? userData) {
  return resolvedNotificationSettings(userData)['globalEnabled'] ?? true;
}

Future<void> actualizarEstadoTokensNotificacion({
  required User user,
  required bool enabled,
}) async {
  final firestore = FirebaseFirestore.instance;
  final tokensSnapshot = await firestore
      .collection('users')
      .doc(user.uid)
      .collection('notificationTokens')
      .get();

  if (tokensSnapshot.docs.isEmpty) return;

  final batch = firestore.batch();

  for (final tokenDoc in tokensSnapshot.docs) {
    batch.update(tokenDoc.reference, {
      'enabled': enabled,
      'lastSeenAt': FieldValue.serverTimestamp(),
    });
  }

  await batch.commit();
}

Future<void> guardarTokenNotificaciones({
  required User user,
  required String token,
}) async {
  if (token.trim().isEmpty) return;

  final firestore = FirebaseFirestore.instance;
  final tokenId = crearNotificationTokenId(token);
  final userDoc = await firestore.collection('users').doc(user.uid).get();
  final tokenEnabled = notificationGlobalEnabledFromData(userDoc.data());

  final tokenRef = firestore
      .collection('users')
      .doc(user.uid)
      .collection('notificationTokens')
      .doc(tokenId);

  await firestore.runTransaction((transaction) async {
    final tokenDoc = await transaction.get(tokenRef);

    final data = {
      'token': token,
      'tokenId': tokenId,
      'platform': obtenerPlatformActual(),
      'enabled': tokenEnabled,
      'lastSeenAt': FieldValue.serverTimestamp(),
    };

    if (tokenDoc.exists) {
      transaction.update(tokenRef, data);
    } else {
      transaction.set(tokenRef, {
        ...data,
        'createdAt': FieldValue.serverTimestamp(),
      });
    }
  });
}

Future<void> registrarTokenNotificaciones(User user) async {
  try {
    final messaging = FirebaseMessaging.instance;

    final settings = await messaging.requestPermission(
      alert: true,
      badge: true,
      sound: true,
      provisional: false,
    );

    final autorizado =
        settings.authorizationStatus == AuthorizationStatus.authorized ||
        settings.authorizationStatus == AuthorizationStatus.provisional;

    if (!autorizado) {
      debugPrint('Notificaciones no autorizadas por el usuario.');
      return;
    }

    await messaging.setAutoInitEnabled(true);

    final token = await messaging.getToken();

    if (token != null && token.isNotEmpty) {
      await guardarTokenNotificaciones(user: user, token: token);
    }

    FirebaseMessaging.instance.onTokenRefresh.listen((newToken) async {
      await guardarTokenNotificaciones(user: user, token: newToken);
    });
  } catch (error) {
    debugPrint('No se pudo registrar el token FCM: $error');
  }
}

Future<String> crearGrupoMinimo({
  required User user,
  required String nombreGrupo,
  required String baseName,
  XFile? groupPhoto,
  String? groupEmoji,
  int? groupColorValue,
}) async {
  final firestore = FirebaseFirestore.instance;

  final groupRef = firestore.collection('groups').doc();
  final memberRef = groupRef.collection('members').doc(user.uid);
  final userGroupRef = firestore
      .collection('users')
      .doc(user.uid)
      .collection('groups')
      .doc(groupRef.id);

  final userDoc = await firestore.collection('users').doc(user.uid).get();
  final rawBasePhotoUrl = userDoc.data()?['basePhotoUrl'];
  final basePhotoUrl = rawBasePhotoUrl is String && rawBasePhotoUrl.trim().isNotEmpty
      ? rawBasePhotoUrl.trim()
      : null;

  final cleanEmoji = groupEmoji?.trim();
  final resolvedEmoji = cleanEmoji == null || cleanEmoji.isEmpty ? null : cleanEmoji;
  final resolvedColorValue = groupColorValue ?? kGroupColorOptions.first.value;

  final batch = firestore.batch();
  final inviteCode = generarCodigoInvitacionDesdeGroupId(groupRef.id);
  final inviteLink = crearEnlaceInvitacion(inviteCode);

  batch.set(groupRef, {
    'name': nombreGrupo,
    'photoUrl': null,
    'photoStoragePath': null,
    'emoji': resolvedEmoji,
    'colorValue': resolvedColorValue,
    'createdAt': FieldValue.serverTimestamp(),
    'lastActivityAt': FieldValue.serverTimestamp(),
    'createdByUid': user.uid,
    'timezone': 'Europe/Madrid',
    'inviteCode': inviteCode,
    'inviteLink': inviteLink,
    'inviteCodeVersion': 1,
    'memberCount': 1,
    'adminsCount': 1,
    'memberLimit': kMaxGroupMembers,
    'deleted': false,
    'deletedAt': null,
    'deletedReason': null,
  });

  batch.set(memberRef, {
    'role': 'admin',
    'joinedAt': FieldValue.serverTimestamp(),
    'statusThisSunday': false,
    'effectiveName': baseName,
    'effectivePhotoUrl': basePhotoUrl,
    'inviteCodeVersionAtJoin': 1,
  });

  batch.set(userGroupRef, {
    'groupId': groupRef.id,
    'role': 'admin',
    'joinedAt': FieldValue.serverTimestamp(),
    'lastViewedAt': null,
    'lastActivityAt': FieldValue.serverTimestamp(),
    'notificationsOverride': 'on',
    'autoDownloadEnabled': false,
    'displayNameSnapshot': nombreGrupo,
    'groupPhotoUrlSnapshot': null,
    'groupEmojiSnapshot': resolvedEmoji,
    'groupColorValueSnapshot': resolvedColorValue,
  });

  await batch.commit();

  if (groupPhoto != null) {
    try {
      final photoUrl = await actualizarFotoGrupo(
        groupId: groupRef.id,
        foto: groupPhoto,
        markActivity: false,
      );

      await userGroupRef.set({
        'groupPhotoUrlSnapshot': photoUrl,
        'lastActivityAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));
    } catch (error) {
      debugPrint('Grupo creado sin foto porque falló la subida: $error');
    }
  }

  return groupRef.id;
}

String generarCodigoInvitacionDesdeGroupId(String groupId) {
  return 'TEMP-$groupId';
}

String crearEnlaceInvitacion(String inviteCode) {
  final code = inviteCode.trim();
  return code.isEmpty ? 'sundayselfie.app' : 'sundayselfie.app/j/$code';
}

String normalizarEntradaInvitacion(String entrada) {
  var value = entrada.trim();

  if (value.isEmpty) return '';

  value = value.replaceAll('\n', '').replaceAll('\t', '').trim();

  final uri = Uri.tryParse(value);
  final queryCode = uri?.queryParameters['code'] ?? uri?.queryParameters['invite'];
  if (queryCode != null && queryCode.trim().isNotEmpty) {
    return queryCode.trim();
  }

  final joinMatch = RegExp(
    r'(?:^|/)(j|join|invite)/([^/?#\s]+)',
    caseSensitive: false,
  ).firstMatch(value);
  if (joinMatch != null) {
    return Uri.decodeComponent(joinMatch.group(2) ?? '').trim();
  }

  final tempMatch = RegExp(
    r'TEMP-[A-Za-z0-9_-]+',
    caseSensitive: false,
  ).firstMatch(value);
  if (tempMatch != null) {
    return tempMatch.group(0)!.trim();
  }

  return value.trim();
}

String? obtenerGroupIdDesdeCodigo(String codigo) {
  final normalizado = normalizarEntradaInvitacion(codigo);
  const prefijo = 'TEMP-';

  if (!normalizado.toUpperCase().startsWith(prefijo)) {
    return null;
  }

  final groupId = normalizado.substring(prefijo.length).trim();

  if (groupId.isEmpty) {
    return null;
  }

  return groupId;
}

int calcularNumeroSemanaISO(DateTime fecha) {
  final jueves = fecha.add(Duration(days: 3 - ((fecha.weekday + 6) % 7)));
  final primerJueves = DateTime(jueves.year, 1, 4);

  return 1 +
      ((jueves.difference(primerJueves).inDays -
                  3 +
                  ((primerJueves.weekday + 6) % 7)) /
              7)
          .floor();
}

int calcularAnioISO(DateTime fecha) {
  final jueves = fecha.add(Duration(days: 3 - ((fecha.weekday + 6) % 7)));
  return jueves.year;
}

String obtenerWeekKeyActual() {
  final ahora = DateTime.now();
  final isoYear = calcularAnioISO(ahora);
  final isoWeek = calcularNumeroSemanaISO(ahora).toString().padLeft(2, '0');

  return '$isoYear-W$isoWeek';
}

String obtenerEtiquetaSemana(String weekKey) {
  final parts = weekKey.split('-W');
  if (parts.length != 2) return weekKey;
  return 'Semana ${parts[1]} / ${parts[0]}';
}

bool esDomingo() {
  return DateTime.now().weekday == DateTime.sunday;
}

int diasHastaDomingo() {
  final weekday = DateTime.now().weekday;
  if (weekday == DateTime.sunday) return 0;
  return DateTime.sunday - weekday;
}

enum SundayWindowPhase { waiting, open, closed }

class SundayWindowState {
  final String weekKey;
  final DateTime openAt;
  final DateTime closeAt;
  final SundayWindowPhase phase;

  const SundayWindowState({
    required this.weekKey,
    required this.openAt,
    required this.closeAt,
    required this.phase,
  });

  bool get canUpload => phase == SundayWindowPhase.open;

  String get phaseLabel {
    switch (phase) {
      case SundayWindowPhase.waiting:
        return 'Esperando al domingo';
      case SundayWindowPhase.open:
        return 'Ventana abierta';
      case SundayWindowPhase.closed:
        return 'Ventana cerrada';
    }
  }

  String get actionLabel {
    switch (phase) {
      case SundayWindowPhase.waiting:
        return 'La próxima ventana se abrirá el domingo';
      case SundayWindowPhase.open:
        return 'Puedes publicar tu selfie semanal';
      case SundayWindowPhase.closed:
        return 'La ventana de subida ya ha cerrado';
    }
  }

  String get shortLabel {
    switch (phase) {
      case SundayWindowPhase.waiting:
        return 'Abre el domingo a las ${formatWindowTime(openAt)}';
      case SundayWindowPhase.open:
        return 'Abierta hasta las ${formatWindowTime(closeAt)}';
      case SundayWindowPhase.closed:
        return 'Cerrada hasta el próximo domingo';
    }
  }
}

SundayWindowState obtenerSundayWindowState({DateTime? now}) {
  final current = now ?? DateTime.now();
  final today = DateTime(current.year, current.month, current.day);

  final daysToSunday = current.weekday == DateTime.sunday
      ? 0
      : DateTime.sunday - current.weekday;
  final sunday = today.add(Duration(days: daysToSunday));

  final openAt = DateTime(sunday.year, sunday.month, sunday.day, 0, 0);
  final closeAt = DateTime(sunday.year, sunday.month, sunday.day, 23, 59, 59, 999);
  final weekKey = obtenerWeekKeyActual();

  SundayWindowPhase phase;

  if (current.isBefore(openAt)) {
    phase = SundayWindowPhase.waiting;
  } else if (current.isBefore(closeAt)) {
    phase = SundayWindowPhase.open;
  } else {
    phase = SundayWindowPhase.closed;
  }

  return SundayWindowState(
    weekKey: weekKey,
    openAt: openAt,
    closeAt: closeAt,
    phase: phase,
  );
}

String formatWindowTime(DateTime date) {
  return '${date.hour.toString().padLeft(2, '0')}:${date.minute.toString().padLeft(2, '0')}';
}

DateTime obtenerObjetivoCountdown(SundayWindowState window) {
  if (window.phase == SundayWindowPhase.open) {
    return window.closeAt;
  }

  if (window.phase == SundayWindowPhase.closed) {
    return window.openAt.add(const Duration(days: 7));
  }

  return window.openAt;
}

Duration obtenerTiempoRestanteVentana(
  SundayWindowState window, {
  DateTime? now,
}) {
  final current = now ?? DateTime.now();
  final target = obtenerObjetivoCountdown(window);
  final remaining = target.difference(current);

  if (remaining.isNegative) {
    return Duration.zero;
  }

  return remaining;
}

String formatCountdown(Duration duration) {
  final days = duration.inDays;
  final hours = duration.inHours.remainder(24);
  final minutes = duration.inMinutes.remainder(60);
  final seconds = duration.inSeconds.remainder(60);

  if (days > 0) {
    return '${days}d ${hours.toString().padLeft(2, '0')}h';
  }

  if (hours > 0) {
    return '${hours}h ${minutes.toString().padLeft(2, '0')}m';
  }

  return '${minutes.toString().padLeft(2, '0')}m ${seconds.toString().padLeft(2, '0')}s';
}

String obtenerTituloCountdown(SundayWindowState window) {
  switch (window.phase) {
    case SundayWindowPhase.waiting:
      return 'Falta para publicar';
    case SundayWindowPhase.open:
      return 'Tiempo restante';
    case SundayWindowPhase.closed:
      return 'Próxima ventana';
  }
}

String obtenerSubtituloCountdown(SundayWindowState window) {
  switch (window.phase) {
    case SundayWindowPhase.waiting:
      return 'La subida se abrirá el domingo a las ${formatWindowTime(window.openAt)}';
    case SundayWindowPhase.open:
      return 'Puedes publicar hasta las ${formatWindowTime(window.closeAt)}';
    case SundayWindowPhase.closed:
      return 'La subida volverá a abrirse el próximo domingo a las ${formatWindowTime(window.openAt)}';
  }
}

int comparableTimestampMillis(dynamic value) {
  if (value is Timestamp) return value.toDate().millisecondsSinceEpoch;
  if (value is DateTime) return value.millisecondsSinceEpoch;
  if (value is int) return value;
  return 0;
}

int semanasActivasDesdeCreatedAt(dynamic createdAt) {
  DateTime? created;

  if (createdAt is Timestamp) {
    created = createdAt.toDate();
  } else if (createdAt is DateTime) {
    created = createdAt;
  }

  if (created == null) return 1;

  final now = DateTime.now();
  final firstSunday = DateTime(created.year, created.month, created.day).add(
    Duration(
      days: created.weekday == DateTime.sunday
          ? 7
          : DateTime.sunday - created.weekday,
    ),
  );

  if (firstSunday.isAfter(now)) return 1;

  return (now.difference(firstSunday).inDays ~/ 7 + 1).clamp(1, 999).toInt();
}

DateTime lunesDeSemanaISO(int isoYear, int isoWeek) {
  final fourthOfJanuary = DateTime(isoYear, 1, 4);
  final firstIsoMonday = fourthOfJanuary.subtract(
    Duration(days: fourthOfJanuary.weekday - DateTime.monday),
  );
  return firstIsoMonday.add(Duration(days: (isoWeek - 1) * 7));
}

String obtenerWeekKeyAnterior(String weekKey) {
  final parts = weekKey.split('-W');
  if (parts.length != 2) return weekKey;

  final isoYear = int.tryParse(parts[0]);
  final isoWeek = int.tryParse(parts[1]);
  if (isoYear == null || isoWeek == null) return weekKey;

  final previousMonday = lunesDeSemanaISO(
    isoYear,
    isoWeek,
  ).subtract(const Duration(days: 7));
  final previousYear = calcularAnioISO(previousMonday);
  final previousWeek = calcularNumeroSemanaISO(
    previousMonday,
  ).toString().padLeft(2, '0');

  return '$previousYear-W$previousWeek';
}

Future<int> calcularRachaPublicacionUsuarioEnGrupo({
  required String groupId,
  required String uid,
  int maxWeeks = 104,
}) async {
  final firestore = FirebaseFirestore.instance;
  var weekKey = obtenerWeekKeyActual();
  var streak = 0;

  for (var i = 0; i < maxWeeks; i += 1) {
    final postDoc = await firestore
        .collection('groups')
        .doc(groupId)
        .collection('weeks')
        .doc(weekKey)
        .collection('posts')
        .doc(uid)
        .get();

    if (!postDoc.exists) {
      break;
    }

    streak += 1;
    weekKey = obtenerWeekKeyAnterior(weekKey);
  }

  return streak;
}

Future<void> solicitarEntradaAGrupo({
  required User user,
  required String groupId,
  String? inviteInput,
}) async {
  final firestore = FirebaseFirestore.instance;

  final groupRef = firestore.collection('groups').doc(groupId);
  final groupDoc = await groupRef.get();

  if (!groupDoc.exists) {
    throw Exception('No se ha encontrado ningún grupo con esa invitación');
  }

  final groupData = groupDoc.data();
  if (groupData?['deleted'] == true) {
    throw Exception('Este grupo ya no está disponible');
  }

  final rawMemberCount = groupData?['memberCount'] ?? 0;
  final memberCount = rawMemberCount is int
      ? rawMemberCount
      : int.tryParse('$rawMemberCount') ?? 0;

  if (memberCount >= kMaxGroupMembers) {
    throw Exception('Este grupo ya tiene el límite de $kMaxGroupMembers miembros');
  }

  final memberRef = groupRef.collection('members').doc(user.uid);
  final memberDoc = await memberRef.get();

  if (memberDoc.exists) {
    throw Exception('Ya perteneces a este grupo');
  }

  final userGroupRef = firestore
      .collection('users')
      .doc(user.uid)
      .collection('groups')
      .doc(groupId);

  final userGroupDoc = await userGroupRef.get();

  if (userGroupDoc.exists) {
    throw Exception('Ya perteneces a este grupo');
  }

  final joinRequestRef = groupRef.collection('joinRequests').doc(user.uid);

  final existingRequest = await joinRequestRef.get();

  if (existingRequest.exists) {
    throw Exception('Ya has enviado una solicitud');
  }

  final userDoc = await firestore.collection('users').doc(user.uid).get();
  final userData = userDoc.data();

  final baseName = formatUserDisplayName(userData?['baseName'] ?? 'Usuario');
  final basePhotoUrl = userData?['basePhotoUrl'];
  final inviteCodeUsed = normalizarEntradaInvitacion(inviteInput ?? '');

  await joinRequestRef.set({
    'uid': user.uid,
    'baseName': baseName,
    'basePhotoUrl': basePhotoUrl,
    'status': 'pending',
    'inviteCodeUsed': inviteCodeUsed.isEmpty ? null : inviteCodeUsed,
    'requestedAt': FieldValue.serverTimestamp(),
    'updatedAt': FieldValue.serverTimestamp(),
  });
}

Future<void> aceptarSolicitudEntrada({
  required String groupId,
  required String requestUid,
  required String requestBaseName,
  required String? requestBasePhotoUrl,
  required String groupName,
  required String? groupPhotoUrl,
  required int inviteCodeVersion,
}) async {
  final firestore = FirebaseFirestore.instance;

  final groupRef = firestore.collection('groups').doc(groupId);
  final memberRef = groupRef.collection('members').doc(requestUid);
  final userGroupRef = firestore
      .collection('users')
      .doc(requestUid)
      .collection('groups')
      .doc(groupId);
  final joinRequestRef = groupRef.collection('joinRequests').doc(requestUid);

  await firestore.runTransaction((transaction) async {
    final groupDoc = await transaction.get(groupRef);
    final joinRequestDoc = await transaction.get(joinRequestRef);
    final memberDoc = await transaction.get(memberRef);

    if (!groupDoc.exists) {
      throw Exception('El grupo ya no existe');
    }

    if (!joinRequestDoc.exists) {
      throw Exception('La solicitud ya no está disponible');
    }

    if (memberDoc.exists) {
      throw Exception('Este usuario ya pertenece al grupo');
    }

    final groupData = groupDoc.data() as Map<String, dynamic>? ?? {};
    final rawMemberCount = groupData['memberCount'] ?? 0;
    final memberCount = rawMemberCount is int
        ? rawMemberCount
        : int.tryParse('$rawMemberCount') ?? 0;

    if (memberCount >= kMaxGroupMembers) {
      throw Exception('Este grupo ya tiene el límite de $kMaxGroupMembers miembros');
    }

    transaction.set(memberRef, {
      'role': 'member',
      'joinedAt': FieldValue.serverTimestamp(),
      'statusThisSunday': false,
      'effectiveName': requestBaseName,
      'effectivePhotoUrl': requestBasePhotoUrl,
      'inviteCodeVersionAtJoin': inviteCodeVersion,
    });

    transaction.set(userGroupRef, {
      'groupId': groupId,
      'role': 'member',
      'joinedAt': FieldValue.serverTimestamp(),
      'lastViewedAt': null,
      'lastActivityAt': FieldValue.serverTimestamp(),
      'notificationsOverride': 'on',
      'autoDownloadEnabled': false,
      'displayNameSnapshot': groupName,
      'groupPhotoUrlSnapshot': groupPhotoUrl,
      'groupEmojiSnapshot': groupData['emoji'],
      'groupColorValueSnapshot': groupData['colorValue'],
    });

    transaction.update(groupRef, {
      'memberCount': FieldValue.increment(1),
      'lastActivityAt': FieldValue.serverTimestamp(),
    });

    transaction.delete(joinRequestRef);
  });

  await marcarActividadGrupo(groupId: groupId);
}

Future<void> rechazarSolicitudEntrada({
  required String groupId,
  required String requestUid,
}) async {
  final currentUser = FirebaseAuth.instance.currentUser;
  if (currentUser == null) {
    throw Exception('No hay usuario autenticado');
  }

  final firestore = FirebaseFirestore.instance;
  final currentMemberDoc = await firestore
      .collection('groups')
      .doc(groupId)
      .collection('members')
      .doc(currentUser.uid)
      .get();

  if (currentMemberDoc.data()?['role'] != 'admin') {
    throw Exception('Solo un administrador puede rechazar solicitudes');
  }

  await firestore
      .collection('groups')
      .doc(groupId)
      .collection('joinRequests')
      .doc(requestUid)
      .delete();
}

Future<void> hacerAdministradorMiembro({
  required String groupId,
  required String targetUid,
}) async {
  final currentUser = FirebaseAuth.instance.currentUser;
  if (currentUser == null) {
    throw Exception('No hay usuario autenticado');
  }

  if (targetUid == currentUser.uid) {
    throw Exception('Ya eres administrador');
  }

  final firestore = FirebaseFirestore.instance;
  final groupRef = firestore.collection('groups').doc(groupId);
  final currentMemberRef = groupRef.collection('members').doc(currentUser.uid);
  final targetMemberRef = groupRef.collection('members').doc(targetUid);
  final targetUserGroupRef = firestore
      .collection('users')
      .doc(targetUid)
      .collection('groups')
      .doc(groupId);

  await firestore.runTransaction((transaction) async {
    final currentMemberDoc = await transaction.get(currentMemberRef);
    final targetMemberDoc = await transaction.get(targetMemberRef);

    if (currentMemberDoc.data()?['role'] != 'admin') {
      throw Exception('Solo un administrador puede hacer administrador a otro usuario');
    }

    if (!targetMemberDoc.exists) {
      throw Exception('Este usuario ya no pertenece al grupo');
    }

    if (targetMemberDoc.data()?['role'] == 'admin') {
      throw Exception('Este usuario ya es administrador');
    }

    transaction.update(targetMemberRef, {
      'role': 'admin',
      'promotedAt': FieldValue.serverTimestamp(),
      'promotedByUid': currentUser.uid,
    });

    transaction.set(
      targetUserGroupRef,
      {'role': 'admin'},
      SetOptions(merge: true),
    );

    transaction.update(groupRef, {
      'adminsCount': FieldValue.increment(1),
      'lastActivityAt': FieldValue.serverTimestamp(),
    });
  });

  await marcarActividadGrupo(groupId: groupId);
}

Future<void> expulsarMiembroGrupo({
  required String groupId,
  required String targetUid,
}) async {
  final currentUser = FirebaseAuth.instance.currentUser;
  if (currentUser == null) {
    throw Exception('No hay usuario autenticado');
  }

  if (targetUid == currentUser.uid) {
    throw Exception('No puedes expulsarte a ti mismo');
  }

  final firestore = FirebaseFirestore.instance;
  final groupRef = firestore.collection('groups').doc(groupId);
  final currentMemberRef = groupRef.collection('members').doc(currentUser.uid);
  final targetMemberRef = groupRef.collection('members').doc(targetUid);
  final targetUserGroupRef = firestore
      .collection('users')
      .doc(targetUid)
      .collection('groups')
      .doc(groupId);

  await firestore.runTransaction((transaction) async {
    final currentMemberDoc = await transaction.get(currentMemberRef);
    final targetMemberDoc = await transaction.get(targetMemberRef);

    if (currentMemberDoc.data()?['role'] != 'admin') {
      throw Exception('Solo un administrador puede expulsar usuarios');
    }

    if (!targetMemberDoc.exists) {
      throw Exception('Este usuario ya no pertenece al grupo');
    }

    if (targetMemberDoc.data()?['role'] == 'admin') {
      throw Exception('No puedes expulsar a otro administrador');
    }

    transaction.delete(targetMemberRef);
    transaction.delete(targetUserGroupRef);
    transaction.update(groupRef, {
      'memberCount': FieldValue.increment(-1),
      'lastActivityAt': FieldValue.serverTimestamp(),
    });
  });

  await marcarActividadGrupo(groupId: groupId);
}

Future<void> actualizarNombreGrupo({
  required String groupId,
  required String newName,
}) async {
  final currentUser = FirebaseAuth.instance.currentUser;
  if (currentUser == null) {
    throw Exception('No hay usuario autenticado');
  }

  final trimmedName = newName.trim();
  if (trimmedName.isEmpty) {
    throw Exception('El nombre del grupo no puede estar vacío');
  }

  final firestore = FirebaseFirestore.instance;
  final groupRef = firestore.collection('groups').doc(groupId);
  final currentMemberRef = groupRef.collection('members').doc(currentUser.uid);

  await firestore.runTransaction((transaction) async {
    final currentMemberDoc = await transaction.get(currentMemberRef);
    if (currentMemberDoc.data()?['role'] != 'admin') {
      throw Exception('Solo un administrador puede cambiar el nombre del grupo');
    }

    transaction.update(groupRef, {
      'name': trimmedName,
      'updatedAt': FieldValue.serverTimestamp(),
      'lastActivityAt': FieldValue.serverTimestamp(),
    });
  });

  try {
    final membersSnapshot = await groupRef.collection('members').get();
    WriteBatch batch = firestore.batch();
    var batchCount = 0;

    Future<void> commitIfNeeded({bool force = false}) async {
      if (batchCount == 0) return;
      if (!force && batchCount < 430) return;
      await batch.commit();
      batch = firestore.batch();
      batchCount = 0;
    }

    for (final memberDoc in membersSnapshot.docs) {
      final userGroupRef = firestore
          .collection('users')
          .doc(memberDoc.id)
          .collection('groups')
          .doc(groupId);

      batch.set(
        userGroupRef,
        {
          'displayNameSnapshot': trimmedName,
          'lastActivityAt': FieldValue.serverTimestamp(),
        },
        SetOptions(merge: true),
      );
      batchCount += 1;
      await commitIfNeeded();
    }

    await commitIfNeeded(force: true);
  } catch (error) {
    debugPrint('No se pudo propagar el nombre del grupo: $error');
  }
}

Future<String> actualizarFotoGrupo({
  required String groupId,
  required XFile foto,
  bool markActivity = true,
}) async {
  final currentUser = FirebaseAuth.instance.currentUser;
  if (currentUser == null) {
    throw Exception('No hay usuario autenticado');
  }

  final firestore = FirebaseFirestore.instance;
  final groupRef = firestore.collection('groups').doc(groupId);
  final memberRef = groupRef.collection('members').doc(currentUser.uid);
  final memberDoc = await memberRef.get();

  if (memberDoc.data()?['role'] != 'admin') {
    throw Exception('Solo los administradores pueden cambiar la foto del grupo');
  }

  final timestamp = DateTime.now().millisecondsSinceEpoch;
  final storagePath = 'groups/$groupId/profile/group_$timestamp.jpg';
  final storageRef = FirebaseStorage.instance.ref().child(storagePath);

  await storageRef.putFile(
    File(foto.path),
    SettableMetadata(
      contentType: 'image/jpeg',
      customMetadata: {
        'groupId': groupId,
        'uid': currentUser.uid,
        'kind': 'groupPhoto',
      },
    ),
  );

  final downloadUrl = await storageRef.getDownloadURL();

  await groupRef.update({
    'photoUrl': downloadUrl,
    'photoStoragePath': storagePath,
    'updatedAt': FieldValue.serverTimestamp(),
    'lastActivityAt': FieldValue.serverTimestamp(),
  });

  try {
    final membersSnapshot = await groupRef.collection('members').get();
    WriteBatch batch = firestore.batch();
    var batchCount = 0;

    Future<void> commitIfNeeded({bool force = false}) async {
      if (batchCount == 0) return;
      if (!force && batchCount < 430) return;
      await batch.commit();
      batch = firestore.batch();
      batchCount = 0;
    }

    for (final memberDoc in membersSnapshot.docs) {
      final userGroupRef = firestore
          .collection('users')
          .doc(memberDoc.id)
          .collection('groups')
          .doc(groupId);

      batch.set(
        userGroupRef,
        {
          'groupPhotoUrlSnapshot': downloadUrl,
          'lastActivityAt': FieldValue.serverTimestamp(),
        },
        SetOptions(merge: true),
      );
      batchCount += 1;
      await commitIfNeeded();
    }

    await commitIfNeeded(force: true);
  } catch (error) {
    debugPrint('No se pudo propagar la foto del grupo: $error');
  }

  if (markActivity) {
    await marcarActividadGrupo(groupId: groupId);
  }

  return downloadUrl;
}

Future<void> abandonarGrupo({required String groupId}) async {
  final currentUser = FirebaseAuth.instance.currentUser;
  if (currentUser == null) {
    throw Exception('No hay usuario autenticado');
  }

  final firestore = FirebaseFirestore.instance;
  final groupRef = firestore.collection('groups').doc(groupId);
  final memberRef = groupRef.collection('members').doc(currentUser.uid);
  final userGroupRef = firestore
      .collection('users')
      .doc(currentUser.uid)
      .collection('groups')
      .doc(groupId);

  await firestore.runTransaction((transaction) async {
    final groupDoc = await transaction.get(groupRef);
    final memberDoc = await transaction.get(memberRef);

    if (!groupDoc.exists || !memberDoc.exists) {
      throw Exception('Ya no perteneces a este grupo');
    }

    final groupData = groupDoc.data() as Map<String, dynamic>? ?? {};
    final memberData = memberDoc.data() as Map<String, dynamic>? ?? {};
    final role = (memberData['role'] ?? 'member').toString();
    final rawMemberCount = groupData['memberCount'] ?? 1;
    final rawAdminsCount = groupData['adminsCount'] ?? 1;
    final memberCount = rawMemberCount is int
        ? rawMemberCount
        : int.tryParse('$rawMemberCount') ?? 1;
    final adminsCount = rawAdminsCount is int
        ? rawAdminsCount
        : int.tryParse('$rawAdminsCount') ?? 1;

    if (role == 'admin' && adminsCount <= 1 && memberCount > 1) {
      throw Exception(
        'Antes de abandonar el grupo, haz administrador a otro miembro',
      );
    }

    final newMemberCount = (memberCount - 1).clamp(0, 999).toInt();
    final newAdminsCount = role == 'admin'
        ? (adminsCount - 1).clamp(0, 999).toInt()
        : adminsCount;

    transaction.delete(memberRef);
    transaction.delete(userGroupRef);

    final updates = <String, dynamic>{
      'memberCount': newMemberCount,
      'adminsCount': newAdminsCount,
      'lastActivityAt': FieldValue.serverTimestamp(),
    };

    if (newMemberCount == 0) {
      updates['deleted'] = true;
      updates['deletedAt'] = FieldValue.serverTimestamp();
      updates['deletedReason'] = 'empty_group';
    }

    transaction.update(groupRef, updates);
  });
}


Future<void> publicarSelfieReal({
  required String groupId,
  required User user,
  required XFile foto,
}) async {
  final window = obtenerSundayWindowState();

  if (!window.canUpload) {
    throw Exception('La ventana de subida está cerrada');
  }

  final firestore = FirebaseFirestore.instance;
  final storage = FirebaseStorage.instance;

  final now = DateTime.now();
  final isoYear = calcularAnioISO(now);
  final isoWeek = calcularNumeroSemanaISO(now);
  final weekKey = obtenerWeekKeyActual();

  final memberRef = firestore
      .collection('groups')
      .doc(groupId)
      .collection('members')
      .doc(user.uid);

  final memberDoc = await memberRef.get();

  if (!memberDoc.exists) {
    throw Exception('No eres miembro de este grupo');
  }

  final memberData = memberDoc.data() as Map<String, dynamic>;
  final authorName = memberData['effectiveName'] ?? 'Usuario';
  final authorPhotoUrl = memberData['effectivePhotoUrl'];

  final storagePath = 'groups/$groupId/weeks/$weekKey/${user.uid}.jpg';
  final storageRef = storage.ref().child(storagePath);

  await storageRef.putFile(
    File(foto.path),
    SettableMetadata(
      contentType: 'image/jpeg',
      customMetadata: {'groupId': groupId, 'weekKey': weekKey, 'uid': user.uid},
    ),
  );

  final downloadUrl = await storageRef.getDownloadURL();

  final weekRef = firestore
      .collection('groups')
      .doc(groupId)
      .collection('weeks')
      .doc(weekKey);

  final postRef = weekRef.collection('posts').doc(user.uid);

  await firestore.runTransaction((transaction) async {
    final postDoc = await transaction.get(postRef);

    transaction.set(weekRef, {
      'weekKey': weekKey,
      'isoYear': isoYear,
      'isoWeek': isoWeek,
      'createdAt': FieldValue.serverTimestamp(),
      'postCount': 1,
    }, SetOptions(merge: true));

    final postData = {
      'uid': user.uid,
      'authorName': authorName,
      'authorPhotoUrl': authorPhotoUrl,
      'updatedAt': FieldValue.serverTimestamp(),
      'imageUrl': downloadUrl,
      'thumbUrl': downloadUrl,
      'storagePathFull': storagePath,
      'storagePathThumb': storagePath,
      'hasAnyReactions': false,
      'selfReactionEmoji': null,
    };

    if (postDoc.exists) {
      transaction.update(postRef, postData);
    } else {
      transaction.set(postRef, {
        ...postData,
        'createdAt': FieldValue.serverTimestamp(),
      });
    }

    transaction.set(
      firestore.collection('users').doc(user.uid).collection('groups').doc(groupId),
      {
        'groupId': groupId,
        'lastActivityAt': FieldValue.serverTimestamp(),
      },
      SetOptions(merge: true),
    );
  });

  await marcarActividadGrupo(groupId: groupId);
}

Future<void> reaccionarASelfie({
  required String groupId,
  required String weekKey,
  required String postUid,
  required String emoji,
}) async {
  final currentUser = FirebaseAuth.instance.currentUser;

  if (currentUser == null) {
    throw Exception('No hay usuario autenticado');
  }

  if (postUid == currentUser.uid) {
    throw Exception('No puedes reaccionar a tu propio selfie');
  }

  final cleanEmoji = normalizarEmojiReaccion(emoji);
  if (cleanEmoji.isEmpty) {
    throw Exception('Elige una reacción válida');
  }

  final firestore = FirebaseFirestore.instance;

  final memberRef = firestore
      .collection('groups')
      .doc(groupId)
      .collection('members')
      .doc(currentUser.uid);

  final memberDoc = await memberRef.get();
  final memberData = memberDoc.data();

  final reactionAuthorName = memberData?['effectiveName'] ?? 'Usuario';
  final reactionAuthorPhotoUrl = memberData?['effectivePhotoUrl'];

  final reactionRef = firestore
      .collection('groups')
      .doc(groupId)
      .collection('weeks')
      .doc(weekKey)
      .collection('posts')
      .doc(postUid)
      .collection('reactions')
      .doc(currentUser.uid);

  await firestore.runTransaction((transaction) async {
    final reactionDoc = await transaction.get(reactionRef);

    final reactionData = {
      'uid': currentUser.uid,
      'emoji': cleanEmoji,
      'authorName': reactionAuthorName,
      'authorPhotoUrl': reactionAuthorPhotoUrl,
      'updatedAt': FieldValue.serverTimestamp(),
    };

    if (reactionDoc.exists) {
      transaction.update(reactionRef, reactionData);
    } else {
      transaction.set(reactionRef, {
        ...reactionData,
        'createdAt': FieldValue.serverTimestamp(),
      });
    }
  });

  await marcarActividadGrupo(groupId: groupId);
}


Future<void> enviarZumbidoSelfie({
  required String groupId,
  required String groupName,
  required String targetUid,
  required String targetName,
}) async {
  final currentUser = FirebaseAuth.instance.currentUser;

  if (currentUser == null) {
    throw Exception('No hay usuario autenticado');
  }

  if (targetUid == currentUser.uid) {
    throw Exception('No puedes enviarte un zumbido a ti mismo');
  }

  if (!esDomingo()) {
    throw Exception('Los recordatorios solo están disponibles los domingos');
  }

  final firestore = FirebaseFirestore.instance;
  final weekKey = obtenerWeekKeyActual();
  final reminderId = '${currentUser.uid}_$targetUid';

  final senderMemberRef = firestore
      .collection('groups')
      .doc(groupId)
      .collection('members')
      .doc(currentUser.uid);

  final targetMemberRef = firestore
      .collection('groups')
      .doc(groupId)
      .collection('members')
      .doc(targetUid);

  final targetPostRef = firestore
      .collection('groups')
      .doc(groupId)
      .collection('weeks')
      .doc(weekKey)
      .collection('posts')
      .doc(targetUid);

  final reminderRef = firestore
      .collection('groups')
      .doc(groupId)
      .collection('weeks')
      .doc(weekKey)
      .collection('reminders')
      .doc(reminderId);

  await firestore.runTransaction((transaction) async {
    final senderMemberDoc = await transaction.get(senderMemberRef);
    final targetMemberDoc = await transaction.get(targetMemberRef);
    final targetPostDoc = await transaction.get(targetPostRef);
    final existingReminderDoc = await transaction.get(reminderRef);

    if (!senderMemberDoc.exists) {
      throw Exception('No perteneces a este grupo');
    }

    if (!targetMemberDoc.exists) {
      throw Exception('Este usuario ya no pertenece al grupo');
    }

    if (targetPostDoc.exists) {
      throw Exception('$targetName ya ha publicado esta semana');
    }

    if (existingReminderDoc.exists) {
      throw Exception('Ya le has enviado un zumbido esta semana');
    }

    final senderData = senderMemberDoc.data() as Map<String, dynamic>? ?? {};
    final targetData = targetMemberDoc.data() as Map<String, dynamic>? ?? {};
    final senderName = formatUserDisplayName(
      senderData['effectiveName'] ?? currentUser.displayName ?? 'Usuario',
    );
    final senderPhotoUrl = senderData['effectivePhotoUrl'];
    final resolvedTargetName = formatUserDisplayName(
      targetData['effectiveName'] ?? targetName,
    );
    final targetPhotoUrl = targetData['effectivePhotoUrl'];

    transaction.set(reminderRef, {
      'type': 'friend_reminder',
      'groupId': groupId,
      'groupName': groupName,
      'weekKey': weekKey,
      'senderUid': currentUser.uid,
      'senderName': senderName,
      'senderPhotoUrl': senderPhotoUrl,
      'targetUid': targetUid,
      'targetName': resolvedTargetName,
      'targetPhotoUrl': targetPhotoUrl,
      'createdAt': FieldValue.serverTimestamp(),
      'updatedAt': FieldValue.serverTimestamp(),
      'notificationStatus': 'pending',
      'notificationSentAt': null,
      'readAt': null,
    });
  });

  await marcarActividadGrupo(groupId: groupId);
}


Future<void> enviarMensajeChatSemana({
  required String groupId,
  required String weekKey,
  required String text,
}) async {
  final currentUser = FirebaseAuth.instance.currentUser;

  if (currentUser == null) {
    throw Exception('No hay usuario autenticado');
  }

  final cleanText = text.trim();

  if (cleanText.isEmpty) {
    throw Exception('Escribe un mensaje');
  }

  if (cleanText.characters.length > 500) {
    throw Exception('El mensaje no puede superar 500 caracteres');
  }

  if (!esDomingo() || weekKey != obtenerWeekKeyActual()) {
    throw Exception('El chat solo está abierto los domingos');
  }

  final firestore = FirebaseFirestore.instance;
  final memberRef = firestore
      .collection('groups')
      .doc(groupId)
      .collection('members')
      .doc(currentUser.uid);

  final memberDoc = await memberRef.get();

  if (!memberDoc.exists) {
    throw Exception('No perteneces a este grupo');
  }

  final memberData = memberDoc.data() as Map<String, dynamic>? ?? {};
  final authorName = formatUserDisplayName(
    memberData['effectiveName'] ?? currentUser.displayName ?? 'Usuario',
  );
  final authorPhotoUrl = memberData['effectivePhotoUrl'];

  final weekRef = firestore
      .collection('groups')
      .doc(groupId)
      .collection('weeks')
      .doc(weekKey);
  final messageRef = weekRef.collection('chatMessages').doc();
  final now = DateTime.now();

  await firestore.runTransaction((transaction) async {
    final weekDoc = await transaction.get(weekRef);

    if (!weekDoc.exists) {
      transaction.set(weekRef, {
        'weekKey': weekKey,
        'isoYear': calcularAnioISO(now),
        'isoWeek': calcularNumeroSemanaISO(now),
        'createdAt': FieldValue.serverTimestamp(),
        'postCount': 0,
      });
    }

    transaction.set(messageRef, {
      'uid': currentUser.uid,
      'authorName': authorName,
      'authorPhotoUrl': authorPhotoUrl,
      'text': cleanText,
      'weekKey': weekKey,
      'createdAt': FieldValue.serverTimestamp(),
    });
  });

  await marcarActividadGrupo(groupId: groupId);
}


class StreakRankingEntry {
  final String uid;
  final String name;
  final String? photoUrl;
  final int streak;
  final bool isCurrentUser;

  const StreakRankingEntry({
    required this.uid,
    required this.name,
    required this.photoUrl,
    required this.streak,
    required this.isCurrentUser,
  });
}

Future<List<StreakRankingEntry>> calcularRankingRachasGrupo({
  required String groupId,
  required String currentUid,
}) async {
  final firestore = FirebaseFirestore.instance;
  final membersSnapshot = await firestore
      .collection('groups')
      .doc(groupId)
      .collection('members')
      .get();

  final entries = <StreakRankingEntry>[];

  for (final memberDoc in membersSnapshot.docs) {
    final data = memberDoc.data();
    final name = formatUserDisplayName(data['effectiveName'] ?? 'Usuario');
    final photoUrl = data['effectivePhotoUrl'] as String?;
    final streak = await calcularRachaPublicacionUsuarioEnGrupo(
      groupId: groupId,
      uid: memberDoc.id,
    );

    entries.add(
      StreakRankingEntry(
        uid: memberDoc.id,
        name: name,
        photoUrl: photoUrl,
        streak: streak,
        isCurrentUser: memberDoc.id == currentUid,
      ),
    );
  }

  entries.sort((a, b) {
    final streakCompare = b.streak.compareTo(a.streak);
    if (streakCompare != 0) return streakCompare;
    return a.name.toLowerCase().compareTo(b.name.toLowerCase());
  });

  return entries;
}

Future<List<XFile>> descargarSelfiesGrupo({
  required String groupId,
  required String groupName,
  required bool allWeeks,
  String? weekKey,
}) async {
  final firestore = FirebaseFirestore.instance;
  final sanitizedGroupName = groupName
      .replaceAll(RegExp(r'[^A-Za-z0-9_\-]+'), '_')
      .replaceAll(RegExp(r'_+'), '_')
      .trim();

  final weekIds = <String>[];

  if (allWeeks) {
    final weeksSnapshot = await firestore
        .collection('groups')
        .doc(groupId)
        .collection('weeks')
        .orderBy('createdAt', descending: true)
        .get();
    weekIds.addAll(weeksSnapshot.docs.map((doc) => doc.id));
  } else {
    weekIds.add(weekKey ?? obtenerWeekKeyActual());
  }

  final files = <XFile>[];
  final httpClient = HttpClient();

  try {
    for (final currentWeekKey in weekIds) {
      final postsSnapshot = await firestore
          .collection('groups')
          .doc(groupId)
          .collection('weeks')
          .doc(currentWeekKey)
          .collection('posts')
          .get();

      for (final postDoc in postsSnapshot.docs) {
        final data = postDoc.data();
        final imageUrl = (data['imageUrl'] ?? data['thumbUrl'] ?? '').toString();
        if (imageUrl.trim().isEmpty) continue;

        final authorName = formatUserDisplayName(data['authorName'] ?? postDoc.id)
            .replaceAll(RegExp(r'[^A-Za-z0-9_\-]+'), '_')
            .replaceAll(RegExp(r'_+'), '_')
            .trim();
        final uri = Uri.tryParse(imageUrl);
        if (uri == null) continue;

        final request = await httpClient.getUrl(uri);
        final response = await request.close();
        if (response.statusCode < 200 || response.statusCode >= 300) continue;

        final bytes = await consolidateHttpClientResponseBytes(response);
        final fileName = '${sanitizedGroupName.isEmpty ? 'grupo' : sanitizedGroupName}_${currentWeekKey}_${authorName.isEmpty ? postDoc.id : authorName}.jpg';
        final file = File('${Directory.systemTemp.path}/$fileName');
        await file.writeAsBytes(bytes, flush: true);
        files.add(XFile(file.path, mimeType: 'image/jpeg', name: fileName));
      }
    }
  } finally {
    httpClient.close(force: true);
  }

  return files;
}

Future<void> compartirArchivosDescargados({
  required BuildContext context,
  required List<XFile> files,
  required String title,
}) async {
  if (files.isEmpty) {
    if (context.mounted) {
      showSundaySnack(context, 'No hay selfies para descargar');
    }
    return;
  }

  await SharePlus.instance.share(
    ShareParams(
      files: files,
      text: title,
      subject: title,
      sharePositionOrigin: const Rect.fromLTWH(0, 0, 1, 1),
    ),
  );
}

