  });

  @override
  State<OnboardingPhotoScreen> createState() => _OnboardingPhotoScreenState();
}

class _OnboardingPhotoScreenState extends State<OnboardingPhotoScreen> {
  XFile? selectedPhoto;
  bool filterApplied = false;
  bool saving = false;

  Future<void> _choosePhotoSource() async {
    final source = await showModalBottomSheet<image_picker.ImageSource>(
      context: context,
      backgroundColor: Colors.transparent,
      builder: (_) => const ProfilePhotoSourceSheet(),
    );

    if (!mounted || source == null) return;

    if (source == image_picker.ImageSource.camera) {
      final photo = await Navigator.push<XFile>(
        context,
        MaterialPageRoute(
          builder: (_) => const CameraCaptureScreen(groupName: 'Foto de perfil'),
        ),
      );

      if (!mounted || photo == null) return;

      setState(() {
        selectedPhoto = photo;
        filterApplied = false;
      });
      return;
    }

    try {
      final picker = image_picker.ImagePicker();
      final photo = await picker.pickImage(
        source: image_picker.ImageSource.gallery,
        imageQuality: 88,
        maxWidth: 1600,
      );

      if (!mounted || photo == null) return;

      setState(() {
        selectedPhoto = photo;
        filterApplied = false;
      });
    } catch (error) {
      if (!mounted) return;
      showSundaySnack(context, 'No se pudo abrir la galería: $error');
    }
  }

  void _applyFilter() {
    if (selectedPhoto == null) {
      showSundaySnack(context, 'Primero añade una foto de perfil');
      return;
    }

    setState(() => filterApplied = true);
  }

  Future<void> _finish() async {
    final photo = selectedPhoto;

    if (photo == null) {
      showSundaySnack(context, 'Añade una foto de perfil para empezar');
      return;
    }

    if (!filterApplied) {
      showSundaySnack(context, 'Aplica el filtro Sunday Selfie para continuar');
      return;
    }

    if (saving) return;

    setState(() => saving = true);

    try {
      await actualizarPerfilInicialUsuario(
        user: widget.user,
        nombre: widget.name,
        foto: photo,
      );

      if (!mounted) return;
      Navigator.popUntil(context, (route) => route.isFirst);
    } catch (error) {
      if (!mounted) return;
      showSundaySnack(context, 'Error guardando perfil: $error');
    } finally {
      if (mounted) setState(() => saving = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: ssBg,
      body: SafeArea(
        child: Column(
          children: [
            const AppHeader(logoTapToHome: false),
            const OnboardingProgress(currentStep: 2, totalSteps: 2),
            Expanded(
              child: ListView(
                padding: const EdgeInsets.fromLTRB(24, 28, 24, 24),
                children: [
                  const Text(
                    'Foto de perfil',
                    style: TextStyle(
                      color: ssTitle,
                      fontSize: 26,
                      fontWeight: FontWeight.w800,
                      height: 1.1,
                    ),
                  ),
                  const SizedBox(height: 8),
                  const Text(
                    'La foto de perfil se puede cambiar cada domingo',
                    style: TextStyle(
                      color: ssText2,
                      fontSize: 14,
                      height: 1.45,
                      fontWeight: FontWeight.w500,
                    ),
                  ),
                  const SizedBox(height: 28),
                  Center(
                    child: OnboardingProfilePhotoPreview(
                      photo: selectedPhoto,
                      name: widget.name,
                      filterApplied: filterApplied,
                      onTap: saving ? null : _choosePhotoSource,
                    ),
                  ),
                  const SizedBox(height: 28),
                  if (selectedPhoto == null)
                    SundayDashedActionCard(
                      icon: Icons.add_a_photo_outlined,
                      title: 'Añadir foto de perfil',
                      subtitle: 'Elige una imagen de galería o hazla ahora',
                      onTap: saving ? null : _choosePhotoSource,
                    )
                  else if (!filterApplied)
                    SundayDashedActionCard(
                      icon: Icons.auto_awesome_rounded,
                      title: 'Aplicar filtro Sunday Selfie',
                      subtitle: 'Toca para añadir el filtro a tu foto',
                      onTap: saving ? null : _applyFilter,
                    )
                  else
                    Container(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 16,
                        vertical: 14,
                      ),
                      decoration: BoxDecoration(
                        color: ssOrangeLight,
                        borderRadius: BorderRadius.circular(14),
                        border: Border.all(color: ssOrangeMid, width: 1.5),
                      ),
                      child: const Row(
                        children: [
                          CircleAvatar(
                            radius: 20,
                            backgroundColor: ssOrange,
                            child: Icon(
                              Icons.check_rounded,
                              color: Colors.white,
                              size: 24,
                            ),
                          ),
                          SizedBox(width: 12),
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text(
                                  'Filtro Sunday Selfie aplicado',
                                  style: TextStyle(
                                    color: ssOrangeDark,
                                    fontSize: 14,
                                    fontWeight: FontWeight.w800,
                                  ),
                                ),
                                SizedBox(height: 2),
                                Text(
                                  'Tu perfil está listo para empezar',
                                  style: TextStyle(
                                    color: ssText2,
                                    fontSize: 12,
                                    fontWeight: FontWeight.w600,
                                  ),
                                ),
                              ],
                            ),
                          ),
                        ],
                      ),
                    ),
                ],
              ),
            ),
            Padding(
              padding: const EdgeInsets.fromLTRB(24, 10, 24, 24),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  SundayButton(
                    text: saving ? 'Guardando...' : '¡Empezar!',
                    onPressed: saving ? null : _finish,
                  ),
                  const SizedBox(height: 10),
                  SundayButton(
                    text: 'Atrás',
                    variant: SundayButtonVariant.ghost,
                    onPressed: saving ? null : () => Navigator.pop(context),
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

