class _HomeScreenState extends State<HomeScreen> {
  final TextEditingController groupController = TextEditingController();
  final TextEditingController codeController = TextEditingController();
  bool creating = false;
  bool joining = false;

  @override
  void dispose() {
    groupController.dispose();
    codeController.dispose();
    super.dispose();
  }

  Future<void> _showCreateJoinSheet(String baseName) async {
    final parentContext = context;

    await showModalBottomSheet(
      context: context,
      backgroundColor: Colors.white,
      isScrollControlled: true,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(28)),
      ),
      builder: (sheetContext) {
        return SafeArea(
          top: false,
          child: Padding(
            padding: const EdgeInsets.fromLTRB(24, 20, 24, 28),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Center(
                  child: Container(
                    width: 36,
                    height: 4,
                    decoration: BoxDecoration(
                      color: ssBorder,
                      borderRadius: BorderRadius.circular(4),
                    ),
                  ),
                ),
                const SizedBox(height: 22),
                const Text(
                  '¿Qué quieres hacer?',
                  style: TextStyle(
                    fontSize: 19,
                    fontWeight: FontWeight.w900,
                    color: ssText,
                  ),
                ),
                const SizedBox(height: 20),
                SundayActionCard(
                  icon: Icons.add_rounded,
                  title: 'Crear un grupo nuevo',
                  subtitle: 'Elige un nombre y empieza como administrador.',
                  onTap: () {
                    Navigator.pop(sheetContext);
                    Future.microtask(() {
                      Navigator.of(parentContext).push(
                        MaterialPageRoute(
                          builder: (_) => CreateGroupScreen(
                            user: widget.user,
                            baseName: baseName,
                          ),
                        ),
                      );
                    });
                  },
                ),
                const SizedBox(height: 12),
                SundayActionCard(
                  icon: Icons.link_rounded,
                  title: 'Unirme con enlace',
                  subtitle:
                      'Introduce el código que te ha pasado un administrador.',
                  onTap: () {
                    Navigator.pop(sheetContext);
                    Future.microtask(() {
                      Navigator.of(parentContext).push(
                        MaterialPageRoute(
                          builder: (_) => JoinGroupScreen(user: widget.user),
                        ),
                      );
                    });
                  },
                ),
              ],
            ),
          ),
        );
      },
    );
  }

  @override
  Widget build(BuildContext context) {
    final userRef = FirebaseFirestore.instance
        .collection('users')
        .doc(widget.user.uid);
    final userGroupsRef = userRef.collection('groups');

    return StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
      stream: userRef.snapshots(),
      builder: (context, userSnapshot) {
        final userData = userSnapshot.data?.data();
        final baseName = formatUserDisplayName(userData?['baseName'] ?? 'Usuario');

        return Scaffold(
          backgroundColor: ssBg,
          body: SafeArea(
            child: Column(
              children: [
                const AppHeader(),
                Expanded(
                  child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
                    stream: userGroupsRef.snapshots(),
                    builder: (context, groupsSnapshot) {
                      if (groupsSnapshot.connectionState ==
                          ConnectionState.waiting) {
                        return const Center(
                          child: CircularProgressIndicator(color: ssOrange),
                        );
                      }

                      if (groupsSnapshot.hasError) {
                        return Center(
                          child: Text(
                            'Error cargando grupos: ${groupsSnapshot.error}',
                          ),
                        );
                      }

                      final groupDocs = [
                        ...(groupsSnapshot.data?.docs ?? []),
                      ]..sort((a, b) {
                          final aData = a.data();
                          final bData = b.data();
                          final aValue = comparableTimestampMillis(
                            aData['lastActivityAt'] ?? aData['joinedAt'],
                          );
                          final bValue = comparableTimestampMillis(
                            bData['lastActivityAt'] ?? bData['joinedAt'],
                          );
                          return bValue.compareTo(aValue);
                        });

                      return ListView(
                        padding: const EdgeInsets.fromLTRB(16, 0, 16, 18),
                        children: [
                          const SundayBanner(),
                          const SizedBox(height: 21),
                          LayoutBuilder(
                            builder: (context, constraints) {
                              final compact = constraints.maxWidth < 350;

                              return Row(
                                crossAxisAlignment: CrossAxisAlignment.center,
                                children: [
                                  Expanded(
                                    child: Text(
                                      'Mis grupos',
                                      maxLines: 1,
                                      overflow: TextOverflow.ellipsis,
                                      style: TextStyle(
                                        color: ssTitle,
                                        fontSize: compact ? 20 : 22,
                                        fontWeight: FontWeight.w800,
                                        height: 1,
                                      ),
                                    ),
                                  ),
                                  const SizedBox(width: 8),
                                  SmallPillButton(
                                    text: '+ Nuevo grupo',
                                    onTap: () => _showCreateJoinSheet(baseName),
                                  ),
                                ],
                              );
                            },
                          ),
                          const SizedBox(height: 16),
                          if (groupDocs.isEmpty) ...[
                            EmptyGroupsCard(
                              onTap: () => _showCreateJoinSheet(baseName),
                            ),
                            const SizedBox(height: 8),
                            InviteHintCard(
                              onTap: () => _showCreateJoinSheet(baseName),
                            ),
                          ] else ...[
                            ...groupDocs.map(
                              (doc) => RealGroupCard(
                                userGroupDoc: doc,
                                onTap: () {
                                  final data = doc.data();
                                  final groupId = (data['groupId'] ?? doc.id).toString();
                                  Navigator.push(
                                    context,
                                    MaterialPageRoute(
                                      builder: (_) =>
                                          GroupScreen(groupId: groupId),
                                    ),
                                  );
                                },
                              ),
                            ),
                            const SizedBox(height: 2),
                            InviteHintCard(
                              onTap: () => _showCreateJoinSheet(baseName),
                            ),
                          ],
                        ],
                      );
                    },
                  ),
                ),
              ],
            ),
          ),
        );
      },
    );
  }
}

class RealGroupCard extends StatelessWidget {
  final QueryDocumentSnapshot<Map<String, dynamic>> userGroupDoc;
  final VoidCallback onTap;

  const RealGroupCard({
    super.key,
    required this.userGroupDoc,
    required this.onTap,
  });

  @override
  Widget build(BuildContext context) {
    final data = userGroupDoc.data();
    final groupId = (data['groupId'] ?? userGroupDoc.id).toString();
    final snapshotName = data['displayNameSnapshot'] ?? 'Grupo';
    final weekKey = obtenerWeekKeyActual();
    final currentUid = FirebaseAuth.instance.currentUser?.uid;

    final groupRef = FirebaseFirestore.instance
        .collection('groups')
        .doc(groupId);
    final postsRef = groupRef
        .collection('weeks')
        .doc(weekKey)
        .collection('posts');

    return StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
      stream: groupRef.snapshots(),
      builder: (context, groupSnapshot) {
        final groupData = groupSnapshot.data?.data();
        final name = groupData?['name'] ?? snapshotName;
        final memberCountRaw = groupData?['memberCount'] ?? 0;
        final memberCount = memberCountRaw is int
            ? memberCountRaw
            : int.tryParse('$memberCountRaw') ?? 0;
        final deleted = groupData?['deleted'] == true;
        final activeWeeks = semanasActivasDesdeCreatedAt(
          groupData?['createdAt'],
        );

        if (deleted) return const SizedBox.shrink();

        return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
          stream: postsRef.snapshots(),
          builder: (context, postsSnapshot) {
            final postDocs = postsSnapshot.data?.docs ?? [];
            final postedCount = postDocs.length;
            final remaining = (memberCount - postedCount).clamp(0, 999);

            return SundayCard(
              onTap: onTap,
              margin: const EdgeInsets.only(bottom: 12),
              padding: const EdgeInsets.fromLTRB(16, 16, 16, 16),
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  GroupIcon(
                    name: name.toString(),
                    photoUrl: groupData?['photoUrl'] as String?,
                    emoji: groupData?['emoji'] as String?,
                    colorValue: groupData?['colorValue'],
                  ),
                  const SizedBox(width: 14),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Row(
                          crossAxisAlignment: CrossAxisAlignment.baseline,
                          textBaseline: TextBaseline.alphabetic,
                          children: [
                            Expanded(
                              child: Text(
                                formatGroupDisplayName(name),
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(
                                  color: ssTitle,
                                  fontSize: 16,
                                  fontWeight: FontWeight.w800,
                                  height: 1.35,
                                ),
                              ),
                            ),
                            Text(
                              '$activeWeeks sem. activo',
                              style: const TextStyle(
                                color: ssText3,
                                fontSize: 11,
                                fontWeight: FontWeight.w600,
                              ),
                            ),
                          ],
                        ),
                        const SizedBox(height: 2),
                        Text(
                          '$memberCount miembros · $postedCount/$memberCount han publicado',
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(
                            color: ssText2,
                            fontSize: 12.8,
                            fontWeight: FontWeight.w600,
                            height: 1.35,
                          ),
                        ),
                        const SizedBox(height: 8),
                        Row(
                          children: [
                            Expanded(
                              child: GroupMembersAvatarStrip(
                                groupId: groupId,
                                memberCount: memberCount,
                              ),
                            ),
                            const SizedBox(width: 8),
                            if (currentUid != null)
                              GroupStreakMedal(
                                groupId: groupId,
                                uid: currentUid,
                              ),
                          ],
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            );
          },
        );
      },
    );
  }
}

class CreateGroupScreen extends StatefulWidget {
  final User user;
  final String baseName;

  const CreateGroupScreen({
    super.key,
    required this.user,
    required this.baseName,
  });

  @override
  State<CreateGroupScreen> createState() => _CreateGroupScreenState();
}

class _CreateGroupScreenState extends State<CreateGroupScreen> {
  final TextEditingController nameController = TextEditingController();
  XFile? selectedGroupPhoto;
  String? selectedGroupEmoji;
  int selectedGroupColorValue = kGroupColorOptions.first.value;
  bool creating = false;

  @override
  void dispose() {
    nameController.dispose();
    super.dispose();
  }

  Future<void> _pickGroupPhoto() async {
    if (creating) return;

    try {
      final picker = image_picker.ImagePicker();
      final photo = await picker.pickImage(
        source: image_picker.ImageSource.gallery,
        imageQuality: 88,
        maxWidth: 1600,
      );

      if (!mounted || photo == null) return;

      setState(() {
        selectedGroupPhoto = photo;
        selectedGroupEmoji = null;
      });
    } catch (error) {
      if (!mounted) return;
      showSundaySnack(context, 'No se pudo abrir la galería: $error');
    }
  }

  Future<void> _selectEmoji() async {
    if (creating) return;

    final emoji = await showModalBottomSheet<String>(
      context: context,
      backgroundColor: Colors.transparent,
      builder: (_) => GroupEmojiPickerSheet(selectedEmoji: selectedGroupEmoji),
    );

    if (!mounted || emoji == null) return;

    setState(() {
      selectedGroupEmoji = emoji;
      selectedGroupPhoto = null;
    });
  }

  Future<void> _createGroup() async {
    final name = nameController.text.trim();
    if (name.isEmpty || creating) return;

    setState(() => creating = true);

    try {
      final groupId = await crearGrupoMinimo(
        user: widget.user,
        nombreGrupo: name,
        baseName: widget.baseName,
        groupPhoto: selectedGroupPhoto,
        groupEmoji: selectedGroupEmoji,
        groupColorValue: selectedGroupColorValue,
      );
      final inviteCode = generarCodigoInvitacionDesdeGroupId(groupId);

      if (!mounted) return;
      Navigator.pushReplacement(
        context,
        MaterialPageRoute(
          builder: (_) => GroupInviteReadyScreen(
            groupId: groupId,
            groupName: name,
            inviteCode: inviteCode,
          ),
        ),
      );
    } catch (error) {
      if (!mounted) return;
      showSundaySnack(context, 'Error: $error');
    } finally {
      if (mounted) setState(() => creating = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: ssBg,
      body: SafeArea(
        child: Column(
          children: [
            AppHeader(
              subtitle: 'Nuevo grupo',
              onBack: () => Navigator.pop(context),
            ),
            Expanded(
              child: SingleChildScrollView(
                padding: const EdgeInsets.fromLTRB(20, 8, 20, 24),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Center(
                      child: CreateGroupAvatarPicker(
                        photo: selectedGroupPhoto,
                        emoji: selectedGroupEmoji,
                        colorValue: selectedGroupColorValue,
                        name: nameController.text,
                        onTap: _pickGroupPhoto,
                      ),
                    ),
                    const SizedBox(height: 26),
                    const GroupCreationSectionLabel('FOTO O EMOTICONO'),
                    const SizedBox(height: 12),
                    Row(
                      children: [
                        Expanded(
                          child: CreateGroupSourceButton(
                            icon: Icons.image_outlined,
                            label: 'Galería',
                            onTap: _pickGroupPhoto,
                          ),
                        ),
                        const SizedBox(width: 14),
                        Expanded(
                          child: CreateGroupSourceButton(
                            emoji: '😀',
                            label: 'Emoticono',
                            onTap: _selectEmoji,
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 28),
                    const GroupCreationSectionLabel('NOMBRE DEL GRUPO'),
                    const SizedBox(height: 10),
                    SundayTextField(
                      controller: nameController,
                      hintText: 'Ej: Los de siempre',
                      textInputAction: TextInputAction.done,
                      onSubmitted: (_) => _createGroup(),
                    ),
                    const SizedBox(height: 24),
                    const GroupCreationSectionLabel('COLOR'),
                    const SizedBox(height: 12),
                    Wrap(
                      spacing: 18,
                      runSpacing: 16,
                      children: kGroupColorOptions.map((color) {
                        final selected = selectedGroupColorValue == color.value;
                        return GroupColorDot(
                          color: color,
                          selected: selected,
                          onTap: () => setState(
                            () => selectedGroupColorValue = color.value,
                          ),
                        );
                      }).toList(),
                    ),
                    const SizedBox(height: 28),
                    const TimezoneInfoCard(),
                  ],
                ),
              ),
            ),
            Padding(
              padding: const EdgeInsets.fromLTRB(20, 10, 20, 24),
              child: AnimatedBuilder(
                animation: nameController,
                builder: (context, _) {
                  final enabled = nameController.text.trim().isNotEmpty;
                  return SundayButton(
                    text: creating ? 'Creando...' : 'Crear grupo',
                    onPressed: creating || !enabled ? null : _createGroup,
                  );
                },
              ),
            ),
          ],
        ),
      ),
    );
  }
}

