                    filterQuality: FilterQuality.high,
                  )
                : Text(
                    resolvedEmoji,
                    style: const TextStyle(fontSize: 34, height: 1),
                  ),
          ),
          Positioned(
            right: -6,
            bottom: -4,
            child: Container(
              width: 36,
              height: 36,
              decoration: BoxDecoration(
                color: ssTitle,
                shape: BoxShape.circle,
                border: Border.all(color: ssBg, width: 3),
