class JoinGroupScreen extends StatefulWidget {
  final User user;

  const JoinGroupScreen({super.key, required this.user});

  @override
  State<JoinGroupScreen> createState() => _JoinGroupScreenState();
}

class _JoinGroupScreenState extends State<JoinGroupScreen> {
  final TextEditingController codeController = TextEditingController();
  bool joining = false;

  @override
  void dispose() {
    codeController.dispose();
    super.dispose();
  }

  Future<void> _pasteFromClipboard() async {
    final data = await Clipboard.getData(Clipboard.kTextPlain);
    final text = data?.text?.trim();
    if (text == null || text.isEmpty) {
      if (!mounted) return;
      showSundaySnack(context, 'No hay texto copiado');
      return;
    }

    codeController.text = text;
  }

  Future<void> _joinGroup() async {
    final input = codeController.text.trim();
    if (input.isEmpty || joining) return;

    final groupId = obtenerGroupIdDesdeCodigo(input);
    if (groupId == null) {
      showSundaySnack(context, 'Invitación no válida');
      return;
    }

    setState(() => joining = true);

    try {
      await solicitarEntradaAGrupo(
        user: widget.user,
        groupId: groupId,
        inviteInput: input,
      );

      if (!mounted) return;
      Navigator.pushReplacement(
        context,
        MaterialPageRoute(
          builder: (_) => JoinRequestSentScreen(groupId: groupId),
        ),
      );
    } catch (error) {
      if (!mounted) return;
      showSundaySnack(context, 'Error: $error');
    } finally {
      if (mounted) setState(() => joining = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: ssBg,
      body: SafeArea(
        child: Column(
          children: [
            AppHeader(onBack: () => Navigator.pop(context)),
            Expanded(
              child: SingleChildScrollView(
                padding: const EdgeInsets.fromLTRB(24, 14, 24, 24),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    const Text(
                      'Unirme a un grupo',
                      style: TextStyle(
                        color: ssTitle,
                        fontSize: 28,
                        fontWeight: FontWeight.w900,
                        height: 1.1,
                      ),
                    ),
                    const SizedBox(height: 8),
                    const Text(
                      'Pega el enlace o escribe el código de invitación que te hayan enviado.',
                      style: TextStyle(
                        color: ssText2,
                        fontSize: 14,
                        height: 1.45,
                        fontWeight: FontWeight.w500,
                      ),
                    ),
                    const SizedBox(height: 28),
                    const Text(
                      'INVITACIÓN',
                      style: TextStyle(
                        color: ssText3,
                        fontSize: 12,
                        letterSpacing: 1.2,
                        fontWeight: FontWeight.w800,
                      ),
                    ),
                    const SizedBox(height: 8),
                    SundayTextField(
                      controller: codeController,
                      hintText: 'sundayselfie.app/j/...',
                      textInputAction: TextInputAction.done,
                      onSubmitted: (_) => _joinGroup(),
                    ),
                    const SizedBox(height: 10),
                    Align(
                      alignment: Alignment.centerLeft,
                      child: TextButton.icon(
                        onPressed: _pasteFromClipboard,
                        icon: const Icon(Icons.content_paste_rounded, size: 18),
                        label: const Text('Pegar desde portapapeles'),
                        style: TextButton.styleFrom(
                          foregroundColor: ssOrange,
                          textStyle: const TextStyle(
                            fontWeight: FontWeight.w800,
                          ),
                        ),
                      ),
                    ),
                    const SizedBox(height: 18),
                    AnimatedBuilder(
                      animation: codeController,
                      builder: (context, _) {
                        final groupId = obtenerGroupIdDesdeCodigo(
                          codeController.text,
                        );

                        if (codeController.text.trim().isEmpty) {
                          return const JoinInstructionCard();
                        }

                        if (groupId == null) {
                          return const InvalidInviteCard();
                        }

                        return JoinGroupPreviewCard(
                          groupId: groupId,
                          currentUid: widget.user.uid,
                        );
                      },
                    ),
                  ],
                ),
              ),
            ),
            Padding(
              padding: const EdgeInsets.fromLTRB(24, 10, 24, 24),
              child: AnimatedBuilder(
                animation: codeController,
                builder: (context, _) {
                  final valid = obtenerGroupIdDesdeCodigo(codeController.text) != null;
                  return SundayButton(
                    text: joining ? 'Enviando solicitud...' : 'Enviar solicitud',
                    onPressed: joining || !valid ? null : _joinGroup,
                  );
                },
              ),
            ),
          ],
        ),
      ),
    );
  }
}

