String shortGroupHeaderTitle(String groupName) {
  final clean = cleanGroupDisplayName(groupName);
  final parts = clean.split(RegExp(r'\s+')).where((p) => p.trim().isNotEmpty);
  final short = parts.take(2).join(' ');
  return short.isEmpty ? 'Grupo' : short;
}

Color memberAvatarColor(String seed) {
  const colors = [
    ssOrange,
    Color(0xFF64B5F6),
    Color(0xFFA8D8A8),
    Color(0xFFCDB7F6),
    Color(0xFFF8BBD0),
    Color(0xFFFFD966),
    Color(0xFF9ADBE8),
    Color(0xFFF7C59F),
  ];

  final value = seed.codeUnits.fold<int>(0, (sum, code) => sum + code);
  return colors[value % colors.length];
}

class GroupPostsGrid extends StatelessWidget {
  final String groupId;
  final String groupName;
  final String weekKey;
  final int memberCount;

  const GroupPostsGrid({
    super.key,
    required this.groupId,
    required this.groupName,
    required this.weekKey,
    required this.memberCount,
  });

  @override
  Widget build(BuildContext context) {
    if (weekKey.isEmpty) {
      return const Center(
        child: Padding(
          padding: EdgeInsets.all(24),
          child: Text(
            'Aún no hay semanas publicadas en este grupo.',
            textAlign: TextAlign.center,
            style: TextStyle(
              color: ssText3,
              fontSize: 13,
              fontWeight: FontWeight.w700,
            ),
          ),
        ),
      );
    }

    final groupRef = FirebaseFirestore.instance
        .collection('groups')
        .doc(groupId);
    final postsRef = groupRef
        .collection('weeks')
        .doc(weekKey)
        .collection('posts')
        .orderBy('updatedAt', descending: true);

    final membersRef = groupRef.collection('members').orderBy('role');

    return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
      stream: postsRef.snapshots(),
      builder: (context, postsSnapshot) {
        if (postsSnapshot.connectionState == ConnectionState.waiting) {
          return const Center(
            child: CircularProgressIndicator(color: ssOrange),
          );
        }

        if (postsSnapshot.hasError) {
          return Center(
            child: Padding(
              padding: const EdgeInsets.all(24),
              child: Text(
                'Error cargando selfies: ${postsSnapshot.error}',
                textAlign: TextAlign.center,
              ),
            ),
          );
        }

        final postDocs = postsSnapshot.data?.docs ?? [];
        final postedUids = postDocs.map((d) => d.id).toSet();
        final totalMembers = memberCount <= 0 ? postDocs.length : memberCount;

        return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
          stream: membersRef.snapshots(),
          builder: (context, membersSnapshot) {
            final memberDocs = membersSnapshot.data?.docs ?? [];
            final missingMembers = memberDocs
                .where((m) => !postedUids.contains(m.id))
                .toList();

            return CustomScrollView(
              slivers: [
                SliverPadding(
                  padding: const EdgeInsets.fromLTRB(16, 0, 16, 20),
                  sliver: SliverGrid(
                    gridDelegate:
                        const SliverGridDelegateWithFixedCrossAxisCount(
                          crossAxisCount: 2,
                          mainAxisSpacing: 12,
                          crossAxisSpacing: 12,
                          childAspectRatio: 0.56,
                        ),
                    delegate: SliverChildBuilderDelegate((context, index) {
                      if (index < postDocs.length) {
                        final doc = postDocs[index];
                        final post = doc.data();
                        return SelfieTile(
                          groupId: groupId,
                          weekKey: weekKey,
                          postUid: doc.id,
                          post: post,
                          onTap: () {
                            Navigator.push(
                              context,
                              MaterialPageRoute(
                                builder: (_) => SelfieFullScreen(
                                  groupId: groupId,
                                  weekKey: weekKey,
                                  postUid: doc.id,
                                  post: post,
                                  initialIndex: index,
                                  galleryEntries: postDocs.map((postDoc) {
                                    return SelfieViewerEntry(
                                      groupId: groupId,
                                      weekKey: weekKey,
                                      postUid: postDoc.id,
                                      post: postDoc.data(),
                                    );
                                  }).toList(),
                                ),
                              ),
                            );
                          },
                        );
                      }

                      final missingDoc = missingMembers[index - postDocs.length];
                      final missing = missingDoc.data();
                      final name = formatUserDisplayName(missing['effectiveName'] ?? 'Usuario');
                      final photoUrl = missing['effectivePhotoUrl'] as String?;
                      return MissingSelfieTile(
                        groupId: groupId,
                        groupName: groupName,
                        weekKey: weekKey,
                        targetUid: missingDoc.id,
                        name: name,
                        photoUrl: photoUrl,
                      );
                    }, childCount: postDocs.length + missingMembers.length),
                  ),
                ),
              ],
            );
          },
        );
      },
    );
  }
}

class WeeklyChatPanel extends StatefulWidget {
  final String groupId;
  final String weekKey;
  final bool expanded;
  final VoidCallback onToggle;

  const WeeklyChatPanel({
    super.key,
    required this.groupId,
    required this.weekKey,
    required this.expanded,
    required this.onToggle,
  });

  @override
  State<WeeklyChatPanel> createState() => _WeeklyChatPanelState();
}

class _WeeklyChatPanelState extends State<WeeklyChatPanel> {
  final TextEditingController messageController = TextEditingController();
  bool sending = false;

  @override
  void dispose() {
    messageController.dispose();
    super.dispose();
  }

  bool get canWrite {
    return widget.weekKey.isNotEmpty &&
        esDomingo() &&
        widget.weekKey == obtenerWeekKeyActual();
  }

  String get weekLabel {
    if (widget.weekKey == obtenerWeekKeyActual()) {
      return 'ESTA SEMANA';
    }

    final parts = widget.weekKey.split('-W');
    if (parts.length == 2) {
      final weekNumber = int.tryParse(parts[1]) ?? 0;
      if (weekNumber > 0) return 'SEMANA $weekNumber / ${parts[0]}';
    }

    return widget.weekKey.toUpperCase();
  }

  Future<void> _send() async {
    if (sending || !canWrite) return;

    final text = messageController.text.trim();
    if (text.isEmpty) return;

    setState(() => sending = true);

    try {
      await enviarMensajeChatSemana(
        groupId: widget.groupId,
        weekKey: widget.weekKey,
        text: text,
      );

      messageController.clear();
    } catch (error) {
      if (!mounted) return;
      showSundaySnack(context, 'Error: $error');
    } finally {
      if (mounted) setState(() => sending = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    if (widget.weekKey.isEmpty) return const SizedBox.shrink();

    final messagesRef = FirebaseFirestore.instance
        .collection('groups')
        .doc(widget.groupId)
        .collection('weeks')
        .doc(widget.weekKey)
        .collection('chatMessages')
        .orderBy('createdAt', descending: false);

    return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
      stream: messagesRef.snapshots(),
      builder: (context, snapshot) {
        final messages = snapshot.data?.docs ?? [];
        final messageCount = messages.length;

        if (!widget.expanded) {
          return WeeklyChatCollapsedBar(
            canWrite: canWrite,
            messageCount: messageCount,
            onToggle: widget.onToggle,
          );
        }

        final maxPanelHeight = math.min(
          MediaQuery.sizeOf(context).height * 0.43,
          canWrite ? 356.0 : 326.0,
        );

        return Container(
          height: maxPanelHeight,
          decoration: const BoxDecoration(
            color: ssBg,
            border: Border(top: BorderSide(color: ssSeparator, width: 1)),
          ),
          child: Column(
            children: [
              WeeklyChatHeader(
                weekLabel: weekLabel,
                messageCount: messageCount,
              ),
              Expanded(
                child: snapshot.connectionState == ConnectionState.waiting
                    ? const Center(
                        child: CircularProgressIndicator(
                          color: ssOrange,
                          strokeWidth: 2,
                        ),
                      )
                    : messages.isEmpty
                        ? WeeklyChatEmptyState(canWrite: canWrite)
                        : ListView.separated(
                            padding: const EdgeInsets.fromLTRB(12, 4, 12, 12),
                            itemCount: messages.length,
                            separatorBuilder: (_, __) => const SizedBox(height: 8),
                            itemBuilder: (context, index) {
                              final doc = messages[index];
                              return WeeklyChatMessageBubble(
                                message: doc.data(),
                                fallbackSeed: doc.id,
                              );
                            },
                          ),
              ),
              WeeklyChatInputBar(
                canWrite: canWrite,
                sending: sending,
                controller: messageController,
                onSend: _send,
                onToggle: widget.onToggle,
              ),
            ],
          ),
        );
      },
    );
  }
}

