    required this.groupName,
    required this.weekKey,
    required this.targetUid,
    required this.name,
    required this.photoUrl,
  });

  @override
  State<MissingSelfieTile> createState() => _MissingSelfieTileState();
}

class _MissingSelfieTileState extends State<MissingSelfieTile> {
  bool sending = false;

  Future<void> _sendReminder() async {
    if (sending) return;

    setState(() => sending = true);

    try {
      await enviarZumbidoSelfie(
        groupId: widget.groupId,
        groupName: widget.groupName,
        targetUid: widget.targetUid,
        targetName: widget.name,
      );

      if (!mounted) return;
      showSundaySnack(context, 'Recordatorio enviado');
    } catch (error) {
      if (!mounted) return;
      showSundaySnack(context, 'Error: $error');
    } finally {
      if (mounted) setState(() => sending = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final currentUid = FirebaseAuth.instance.currentUser?.uid;
    final isMe = currentUid == widget.targetUid;
    final displayName = formatUserDisplayName(widget.name);

    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        SizedBox(
          height: 32,
          child: Row(
            children: [
              MiniProfileAvatar(
                name: displayName,
                photoUrl: widget.photoUrl,
                size: 24,
                borderColor: ssBg,
              ),
              const SizedBox(width: 8),
              Expanded(
                child: Text(
                  displayName,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(
                    color: ssTitle,
                    fontSize: 13.5,
                    fontWeight: FontWeight.w900,
                    height: 1,
                  ),
                ),
              ),
            ],
          ),
        ),
        Expanded(
          child: CustomPaint(
            painter: const SundayDashedBorderPainter(
              color: ssBorder,
              radius: 18,
              strokeWidth: 1.4,
              dashLength: 4,
              gapLength: 4,
            ),
            child: Container(
              decoration: BoxDecoration(
                color: Colors.white,
                borderRadius: BorderRadius.circular(18),
              ),
              padding: const EdgeInsets.fromLTRB(10, 12, 10, 10),
              child: Column(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  const Spacer(),
                  MiniProfileAvatar(
                    name: displayName,
                    photoUrl: widget.photoUrl,
                    size: 54,
                    borderColor: ssBg,
                  ),
                  const SizedBox(height: 8),
                  Text(
                    displayName,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    textAlign: TextAlign.center,
                    style: const TextStyle(
                      color: ssText3,
                      fontSize: 12,
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                  const SizedBox(height: 4),
                  const Text(
                    'Sunday Selfie pendiente',
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    textAlign: TextAlign.center,
                    style: TextStyle(
                      color: ssText3,
                      fontSize: 10,
                      fontWeight: FontWeight.w500,
                    ),
                  ),
                  const Spacer(),
                ],
              ),
            ),
          ),
        ),
        const SizedBox(height: 8),
        if (isMe || currentUid == null)
          const SizedBox(height: 31)
        else
          MissingSelfieReminderButton(
            groupId: widget.groupId,
            weekKey: widget.weekKey,
            targetUid: widget.targetUid,
            sending: sending,
            onTap: _sendReminder,
          ),
      ],
    );
  }
}

class MissingSelfieReminderButton extends StatelessWidget {
  final String groupId;
  final String weekKey;
  final String targetUid;
  final bool sending;
  final VoidCallback onTap;

  const MissingSelfieReminderButton({
    super.key,
    required this.groupId,
    required this.weekKey,
    required this.targetUid,
    required this.sending,
    required this.onTap,
  });

  @override
  Widget build(BuildContext context) {
    final currentUid = FirebaseAuth.instance.currentUser?.uid;

    if (currentUid == null || !esDomingo()) return const SizedBox.shrink();

    final reminderRef = FirebaseFirestore.instance
        .collection('groups')
        .doc(groupId)
        .collection('weeks')
        .doc(weekKey)
        .collection('reminders')
        .doc('${currentUid}_$targetUid');

    return StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
      stream: reminderRef.snapshots(),
      builder: (context, snapshot) {
        final sent = snapshot.data?.exists ?? false;
        final disabled = sent || sending;

        return Material(
          color: Colors.transparent,
          child: InkWell(
            borderRadius: BorderRadius.circular(999),
            onTap: disabled ? null : onTap,
            child: Container(
              height: 31,
              width: double.infinity,
              padding: const EdgeInsets.symmetric(horizontal: 8),
              alignment: Alignment.center,
              decoration: BoxDecoration(
                color: Colors.white,
                borderRadius: BorderRadius.circular(999),
                border: Border.all(
                  color: disabled ? ssBorder : ssOrangeMid,
                  width: 1.2,
                ),
                boxShadow: [
                  BoxShadow(
                    color: Colors.black.withValues(alpha: 0.045),
                    blurRadius: 8,
                    offset: const Offset(0, 2),
                  ),
                ],
              ),
              child: FittedBox(
                fit: BoxFit.scaleDown,
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Icon(
                      sent
                          ? Icons.check_rounded
                          : Icons.notifications_none_rounded,
                      color: disabled ? ssText3 : ssOrangeDark,
                      size: 13,
                    ),
                    const SizedBox(width: 4),
                    Text(
                      sending
                          ? 'Enviando...'
                          : sent
                              ? 'Recordatorio enviado'
                              : 'Enviar recordatorio',
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: TextStyle(
                        color: disabled ? ssText3 : ssOrangeDark,
                        fontSize: 9.4,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ),
        );
      },
    );
  }
}

class SelfieTile extends StatelessWidget {
  final String groupId;
  final String weekKey;
  final String postUid;
  final Map<String, dynamic> post;
  final VoidCallback onTap;

  const SelfieTile({
    super.key,
    required this.groupId,
    required this.weekKey,
    required this.postUid,
    required this.post,
    required this.onTap,
  });

  @override
  Widget build(BuildContext context) {
    final authorName = formatUserDisplayName(post['authorName'] ?? 'Usuario');
    final postAuthorPhotoUrl = post['authorPhotoUrl'] as String?;
    final imageUrl = (post['thumbUrl'] ?? post['imageUrl'] ?? '').toString();

    final memberRef = FirebaseFirestore.instance
        .collection('groups')
        .doc(groupId)
        .collection('members')
        .doc(postUid);

    final reactionsRef = FirebaseFirestore.instance
        .collection('groups')
        .doc(groupId)
        .collection('weeks')
        .doc(weekKey)
        .collection('posts')
        .doc(postUid)
        .collection('reactions')
        .orderBy('updatedAt', descending: true);

    return Material(
      color: Colors.transparent,
      child: InkWell(
        borderRadius: BorderRadius.circular(18),
        onTap: onTap,
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
              stream: memberRef.snapshots(),
              builder: (context, memberSnapshot) {
                final memberData = memberSnapshot.data?.data();
                final memberPhotoUrl =
                    memberData?['effectivePhotoUrl'] as String?;
                final memberName = formatUserDisplayName(
                    memberData?['effectiveName'] ?? authorName,
                  );
                final resolvedPhotoUrl = postAuthorPhotoUrl != null &&
                        postAuthorPhotoUrl.trim().isNotEmpty
                    ? postAuthorPhotoUrl
                    : memberPhotoUrl;

                return SizedBox(
                  height: 32,
                  child: Row(
                    children: [
                      MiniProfileAvatar(
                        name: memberName,
                        photoUrl: resolvedPhotoUrl,
                        size: 24,
                        borderColor: ssBg,
                      ),
                      const SizedBox(width: 8),
                      Expanded(
                        child: Text(
                          memberName,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(
                            color: ssTitle,
                            fontSize: 13.5,
                            fontWeight: FontWeight.w900,
                            height: 1,
                          ),
                        ),
                      ),
                    ],
                  ),
                );
              },
            ),
            Expanded(
              child: ClipRRect(
                borderRadius: BorderRadius.circular(18),
                child: Container(
                  width: double.infinity,
                  color: ssOrangeLight,
                  child: imageUrl.isNotEmpty
                      ? Image.network(
                          imageUrl,
                          fit: BoxFit.cover,
                          alignment: Alignment.center,
                          filterQuality: FilterQuality.high,
                          loadingBuilder: (context, child, progress) {
                            if (progress == null) return child;
                            return const _ImageLoadingFill();
                          },
                          errorBuilder: (_, __, ___) => Center(
                            child: Text(
                              initialsFromName(authorName),
                              style: const TextStyle(
                                color: Colors.white,
                                fontSize: 38,
                                fontWeight: FontWeight.w800,
                              ),
                            ),
                          ),
                        )
                      : Center(
                          child: Text(
                            initialsFromName(authorName),
                            style: const TextStyle(
                              color: Colors.white,
                              fontSize: 38,
                              fontWeight: FontWeight.w800,
                            ),
                          ),
                        ),
                ),
              ),
            ),
            const SizedBox(height: 8),
            GroupAggregatedReactionsStrip(reactionsRef: reactionsRef),
          ],
        ),
      ),
    );
  }
}


class GroupAggregatedReactionsStrip extends StatelessWidget {
  final Query<Map<String, dynamic>> reactionsRef;
  final bool compact;
  final bool overlay;

  const GroupAggregatedReactionsStrip({
    super.key,
    required this.reactionsRef,
    this.compact = false,
    this.overlay = false,
  });

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
      stream: reactionsRef.snapshots(),
      builder: (context, snapshot) {
        final reactions = snapshot.data?.docs ?? [];
        final counts = <String, int>{};

        for (final reaction in reactions) {
          final emoji = normalizarEmojiReaccion(
            (reaction.data()['emoji'] ?? '').toString(),
          );
          if (emoji.isEmpty) continue;
          counts[emoji] = (counts[emoji] ?? 0) + 1;
        }

        if (counts.isEmpty) {
          return SizedBox(height: compact ? 26 : 31);
        }

        return Container(
          height: compact ? 28 : 31,
          decoration: BoxDecoration(
            color: overlay
                ? Colors.white.withValues(alpha: 0.88)
                : Colors.white,
            borderRadius: BorderRadius.circular(999),
            boxShadow: [
              BoxShadow(
                color: Colors.black.withValues(alpha: overlay ? 0.12 : 0.045),
                blurRadius: overlay ? 10 : 8,
                offset: const Offset(0, 2),
              ),
            ],
          ),
          child: ListView.separated(
            scrollDirection: Axis.horizontal,
            padding: EdgeInsets.symmetric(
              horizontal: compact ? 8 : 10,
              vertical: compact ? 5 : 6,
            ),
            itemCount: counts.length,
            separatorBuilder: (_, __) => SizedBox(width: compact ? 6 : 7),
            itemBuilder: (context, index) {
              final entry = counts.entries.elementAt(index);
              return InkWell(
                borderRadius: BorderRadius.circular(999),
                onTap: () => showReactionUsersSheet(
                  context: context,
                  emoji: entry.key,
                  reactions: reactions,
                ),
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Text(
                      entry.key,
                      style: TextStyle(
                        fontSize: compact ? 13 : 14,
                        height: 1,
                      ),
                    ),
                    if (entry.value > 1) ...[
                      const SizedBox(width: 2),
                      Text(
                        '${entry.value}',
                        style: TextStyle(
                          color: ssTitle,
                          fontSize: compact ? 13 : 14,
                          fontWeight: FontWeight.w900,
                          height: 1,
                          fontFeatures: const [FontFeature.tabularFigures()],
                        ),
                      ),
                    ],
                  ],
                ),
              );
            },
          ),
        );
      },
    );
  }
}

