                ),
              ),
            ),
          );
        },
      ),
    );
  }
}

class FullScreenReactionPanel extends StatelessWidget {
  final List<QueryDocumentSnapshot<Map<String, dynamic>>> reactions;
  final String? myReaction;
  final bool canReact;
  final bool isSending;
  final String disabledMessage;
  final ValueChanged<String> onReact;

  const FullScreenReactionPanel({
    super.key,
    required this.reactions,
    required this.myReaction,
    required this.canReact,
    required this.isSending,
    required this.disabledMessage,
    required this.onReact,
  });

  @override
  Widget build(BuildContext context) {
    final counts = <String, int>{};
    for (final reaction in reactions) {
      final emoji = normalizarEmojiReaccion(
        (reaction.data()['emoji'] ?? '').toString(),
      );
      if (emoji.isEmpty) continue;
      counts[emoji] = (counts[emoji] ?? 0) + 1;
    }

    if (counts.isEmpty && !canReact && disabledMessage.isEmpty) {
      return const SizedBox.shrink();
    }

    return ConstrainedBox(
      constraints: BoxConstraints(
        maxHeight: MediaQuery.sizeOf(context).height * 0.42,
      ),
      child: SingleChildScrollView(
        physics: const BouncingScrollPhysics(),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            if (counts.isNotEmpty)
              Align(
                alignment: Alignment.centerLeft,
                child: Wrap(
                  spacing: 8,
                  runSpacing: 8,
                  children: counts.entries.map((entry) {
                    final selected = myReaction == entry.key;
                    return InkWell(
                      borderRadius: BorderRadius.circular(999),
                      onTap: () => showReactionUsersSheet(
                        context: context,
                        emoji: entry.key,
                        reactions: reactions,
                      ),
                      child: Container(
                        padding: const EdgeInsets.symmetric(
                          horizontal: 12,
                          vertical: 7,
                        ),
                        decoration: BoxDecoration(
                          color: selected
                              ? ssOrange.withValues(alpha: 0.96)
                              : Colors.white.withValues(alpha: 0.90),
                          borderRadius: BorderRadius.circular(999),
                          border: Border.all(
                            color: selected
                                ? ssOrange
                                : Colors.white.withValues(alpha: 0.55),
                          ),
                          boxShadow: [
                            BoxShadow(
                              color: Colors.black.withValues(alpha: 0.12),
                              blurRadius: 10,
                              offset: const Offset(0, 3),
                            ),
                          ],
                        ),
                        child: Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            Text(
                              entry.key,
                              style: const TextStyle(
                                fontSize: 18,
                                height: 1,
                              ),
                            ),
                            if (entry.value > 1) ...[
                              const SizedBox(width: 4),
                              Text(
                                '${entry.value}',
                                style: TextStyle(
                                  color: selected ? Colors.white : ssTitle,
                                  fontSize: 14,
                                  fontWeight: FontWeight.w900,
                                  height: 1,
                                  fontFeatures: const [FontFeature.tabularFigures()],
                                ),
                              ),
                            ],
                          ],
                        ),
                      ),
                    );
                  }).toList(),
                ),
              ),
            if (counts.isNotEmpty && (canReact || disabledMessage.isNotEmpty))
              const SizedBox(height: 12),
            if (canReact)
              EmojiReactionButton(
                currentReaction: myReaction,
                isSending: isSending,
                onReact: onReact,
              )
            else if (disabledMessage.isNotEmpty)
              Container(
                width: double.infinity,
                padding: const EdgeInsets.symmetric(
                  horizontal: 14,
                  vertical: 12,
                ),
                decoration: BoxDecoration(
                  color: Colors.white.withValues(alpha: 0.12),
                  borderRadius: BorderRadius.circular(18),
                  border: Border.all(
                    color: Colors.white.withValues(alpha: 0.10),
                  ),
                ),
                child: Text(
                  disabledMessage,
                  textAlign: TextAlign.center,
                  style: const TextStyle(
                    color: Colors.white70,
                    fontSize: 13,
                    fontWeight: FontWeight.w700,
                  ),
                ),
              ),
          ],
        ),
      ),
    );
  }
}

