class MontageSelfieTile extends StatelessWidget {
  final QueryDocumentSnapshot<Map<String, dynamic>> post;
  final double height;
  final VoidCallback onTap;

  const MontageSelfieTile({
    super.key,
    required this.post,
    required this.height,
    required this.onTap,
  });

  @override
  Widget build(BuildContext context) {
    final data = post.data();
    final imageUrl = (data['thumbUrl'] ?? data['imageUrl'] ?? '').toString();

    final reactionsRef = post.reference
        .collection('reactions')
        .orderBy('updatedAt', descending: true);

    return GestureDetector(
      onTap: onTap,
      child: Container(
        height: height,
        margin: const EdgeInsets.only(bottom: 7),
        clipBehavior: Clip.antiAlias,
        decoration: BoxDecoration(
          color: ssOrangeLight,
          borderRadius: BorderRadius.circular(14),
        ),
        child: Stack(
          fit: StackFit.expand,
          children: [
            if (imageUrl.isNotEmpty)
              Image.network(
                imageUrl,
                fit: BoxFit.cover,
                loadingBuilder: (context, child, progress) {
                  if (progress == null) return child;
                  return const _ImageLoadingFill();
                },
                errorBuilder: (_, __, ___) => const _ImageErrorFill(),
              )
            else
              Container(
                decoration: const BoxDecoration(
                  gradient: LinearGradient(
                    colors: [ssOrange, ssOrangeMid],
                    begin: Alignment.topLeft,
                    end: Alignment.bottomRight,
                  ),
                ),
              ),
            const _PhotoGradientOverlay(),
            Positioned(
              left: 7,
              right: 7,
              bottom: 7,
              child: GroupAggregatedReactionsStrip(
                reactionsRef: reactionsRef,
                compact: true,
                overlay: true,
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class ProfileScreen extends StatefulWidget {
  final User user;

  const ProfileScreen({super.key, required this.user});

  @override
  State<ProfileScreen> createState() => _ProfileScreenState();
}

class _ProfileScreenState extends State<ProfileScreen> {
  Future<void> _confirmSignOut() async {
    final shouldSignOut = await showDialog<bool>(
      context: context,
      builder: (dialogContext) {
        return AlertDialog(
          backgroundColor: Colors.white,
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(22),
          ),
          title: const Text('Cerrar sesión'),
          content: const Text(
            '¿Quieres salir de Sunday Selfie en este dispositivo?',
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext, false),
              child: const Text('Cancelar'),
            ),
            TextButton(
              onPressed: () => Navigator.pop(dialogContext, true),
              child: const Text(
                'Salir',
                style: TextStyle(
                  color: ssOrangeDark,
                  fontWeight: FontWeight.w800,
                ),
              ),
            ),
          ],
        );
      },
    );

    if (shouldSignOut == true) {
      await FirebaseAuth.instance.signOut();
    }
  }

  @override
  Widget build(BuildContext context) {
    final userRef = FirebaseFirestore.instance
        .collection('users')
        .doc(widget.user.uid);
    final userGroupsRef = FirebaseFirestore.instance
        .collection('users')
        .doc(widget.user.uid)
        .collection('groups')
        .orderBy('joinedAt', descending: true);

    return Scaffold(
      backgroundColor: ssBg,
      body: SafeArea(
        child: Column(
          children: [
            const AppHeader(),
            Expanded(
              child: StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
                stream: userRef.snapshots(),
                builder: (context, userSnapshot) {
                  final userData = userSnapshot.data?.data();
                  final rawBaseName = userData?['baseName']?.toString().trim();
                  final authDisplayName = widget.user.displayName?.trim();
                  final baseName = formatUserDisplayName(
                    rawBaseName != null && rawBaseName.isNotEmpty
                        ? rawBaseName
                        : authDisplayName != null && authDisplayName.isNotEmpty
                        ? authDisplayName
                        : 'Usuario',
                  );
                  final basePhotoUrl = userData?['basePhotoUrl'] as String?;
                  final createdAt = timestampToDate(userData?['createdAt']);
                  final memberSince = createdAt == null
                      ? 'Miembro desde ahora'
                      : 'Miembro desde ${monthName(createdAt.month)} ${createdAt.year}';
                  final screenHeight = MediaQuery.sizeOf(context).height;
                  final compactProfile = screenHeight < 780;
                  final profileAvatarSize = compactProfile ? 86.0 : 99.0;
                  final profileTopPadding = compactProfile ? 6.0 : 16.0;
                  final profileBottomPadding = compactProfile ? 14.0 : 24.0;
                  final profileMainGap = compactProfile ? 12.0 : 20.0;
                  final profileMenuGap = compactProfile ? 10.0 : 16.0;

                  return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
                    stream: userGroupsRef.snapshots(),
                    builder: (context, groupsSnapshot) {
                      final groupDocs = groupsSnapshot.data?.docs ?? [];
                      final groupsCount = groupDocs.length;

                      return FutureBuilder<int>(
                        future: countUserSelfies(widget.user.uid, groupDocs),
                        builder: (context, selfiesSnapshot) {
                          final selfiesCount = selfiesSnapshot.data ?? 0;

                          return ListView(
                            padding: const EdgeInsets.fromLTRB(20, 0, 20, 28),
                            children: [
                              Padding(
                                padding: EdgeInsets.fromLTRB(
                                  0,
                                  profileTopPadding,
                                  0,
                                  profileBottomPadding,
                                ),
                                child: Column(
                                  children: [
                                    ProfileAvatar(
                                      name: baseName,
                                      photoUrl: basePhotoUrl,
                                      size: profileAvatarSize,
                                    ),
                                    SizedBox(height: compactProfile ? 12 : 16),
                                    Text(
                                      baseName,
                                      maxLines: 1,
                                      overflow: TextOverflow.ellipsis,
                                      textAlign: TextAlign.center,
                                      style: const TextStyle(
                                        color: ssText,
                                        fontSize: 22,
                                        fontWeight: FontWeight.w900,
                                      ),
                                    ),
                                    const SizedBox(height: 4),
                                    Text(
                                      memberSince,
                                      textAlign: TextAlign.center,
                                      style: const TextStyle(
                                        color: ssText3,
                                        fontSize: 14,
                                        fontWeight: FontWeight.w600,
                                      ),
                                    ),
                                  ],
                                ),
                              ),
                              ProfileStatsBar(
                                groupsCount: groupsCount,
                                activeWeeks: activeWeeksFromGroups(groupDocs),
                                selfiesCount: selfiesCount,
                              ),
                              SizedBox(height: profileMainGap),
                              ProfileSelfiesShortcut(
                                selfiesCount: selfiesCount,
                                onTap: () {
                                  Navigator.push(
                                    context,
                                    MaterialPageRoute(
                                      builder: (_) =>
                                          MySelfiesScreen(user: widget.user),
                                    ),
                                  );
                                },
                              ),
                              SizedBox(height: profileMenuGap),
                              ProfileMenuRow(
                                iconText: '🔔',
                                label: 'Notificaciones',
                                onTap: () {
                                  Navigator.push(
                                    context,
                                    MaterialPageRoute(
                                      builder: (_) =>
                                          NotificationsSettingsScreen(
                                            user: widget.user,
                                          ),
                                    ),
                                  );
                                },
                              ),
                              ProfileMenuRow(
                                iconText: '👤',
                                label: 'Editar perfil',
                                onTap: () {
                                  Navigator.push(
                                    context,
                                    MaterialPageRoute(
                                      builder: (_) =>
                                          EditProfileScreen(user: widget.user),
                                    ),
                                  );
                                },
                              ),
                              ProfileMenuRow(
                                iconText: '⚙️',
                                label: 'Ajustes',
                                onTap: () {
                                  Navigator.push(
                                    context,
                                    MaterialPageRoute(
                                      builder: (_) =>
                                          AppSettingsScreen(user: widget.user),
                                    ),
                                  );
                                },
                              ),
                              const SizedBox(height: 16),
                              TextButton(
                                onPressed: _confirmSignOut,
                                child: const Text(
                                  'Cerrar sesión',
                                  style: TextStyle(
                                    color: Color(0xFFE74C3C),
                                    fontSize: 14,
                                    fontWeight: FontWeight.w700,
                                  ),
                                ),
                              ),
                            ],
                          );
                        },
                      );
                    },
                  );
                },
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class EditProfileScreen extends StatefulWidget {
  final User user;

  const EditProfileScreen({super.key, required this.user});

  @override
  State<EditProfileScreen> createState() => _EditProfileScreenState();
}

class _EditProfileScreenState extends State<EditProfileScreen> {
  final TextEditingController nameController = TextEditingController();
  bool saving = false;
  bool saved = false;
  bool nameInitialized = false;
  XFile? selectedPhoto;
  bool selectedPhotoFilterApplied = false;

  @override
  void dispose() {
    nameController.dispose();
    super.dispose();
  }

  Future<void> _choosePhotoSource() async {
    if (!esDomingo()) {
      showSundaySnack(
        context,
        'La foto de perfil solo se puede cambiar los domingos',
      );
      return;
    }

    final source = await showModalBottomSheet<image_picker.ImageSource>(
      context: context,
      backgroundColor: Colors.transparent,
      builder: (_) => const ProfilePhotoSourceSheet(),
    );

    if (!mounted || source == null) return;

    if (source == image_picker.ImageSource.camera) {
      final photo = await Navigator.push<XFile>(
        context,
        MaterialPageRoute(
          builder: (_) => const CameraCaptureScreen(groupName: 'Foto de perfil'),
        ),
      );

      if (!mounted || photo == null) return;

      setState(() {
        selectedPhoto = photo;
        selectedPhotoFilterApplied = true;
        saved = false;
      });
      return;
    }

    try {
      final picker = image_picker.ImagePicker();
      final photo = await picker.pickImage(
        source: image_picker.ImageSource.gallery,
        imageQuality: 88,
        maxWidth: 1600,
      );

      if (!mounted || photo == null) return;

      setState(() {
        selectedPhoto = photo;
        selectedPhotoFilterApplied = true;
        saved = false;
      });
    } catch (error) {
      if (!mounted) return;
      showSundaySnack(context, 'No se pudo abrir la galería: $error');
    }
  }

  void _applyProfileFilter() {
    if (selectedPhoto == null) {
      showSundaySnack(context, 'Primero elige una foto de perfil');
      return;
    }

    setState(() {
      selectedPhotoFilterApplied = true;
      saved = false;
    });
  }

  Future<void> _saveProfile({
    required String currentName,
    required String? currentPhotoStoragePath,
  }) async {
    final newName = nameController.text.trim();
    final photo = selectedPhoto;
    final nameChanged = newName.isNotEmpty && newName != currentName;
    final photoChanged = photo != null;

    if (newName.isEmpty) {
      showSundaySnack(context, 'El nombre no puede estar vacío');
      return;
    }

    if (!nameChanged && !photoChanged) return;

    if (photoChanged && !esDomingo()) {
      showSundaySnack(
        context,
        'La foto de perfil solo se puede cambiar los domingos',
      );
      return;
    }

    if (photoChanged && !selectedPhotoFilterApplied) {
      showSundaySnack(
        context,
        'Aplica el filtro Sunday Selfie antes de guardar',
      );
      return;
    }

    if (saving) return;

    setState(() => saving = true);

    try {
      if (nameChanged) {
        await actualizarNombreUsuario(widget.user, newName);
      }

      if (photoChanged) {
        await actualizarFotoPerfilUsuario(
          user: widget.user,
          foto: photo,
          previousStoragePath: currentPhotoStoragePath,
        );
      }

      if (!mounted) return;
      FocusScope.of(context).unfocus();
      setState(() {
        selectedPhoto = null;
        selectedPhotoFilterApplied = false;
        saved = true;
        nameInitialized = false;
      });
      showSundaySnack(context, 'Perfil actualizado');
      await Future<void>.delayed(const Duration(milliseconds: 700));
      if (mounted) Navigator.pop(context);
    } catch (error) {
      if (!mounted) return;
      showSundaySnack(context, 'Error: $error');
    } finally {
      if (mounted) setState(() => saving = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final userRef = FirebaseFirestore.instance
        .collection('users')
        .doc(widget.user.uid);

    return Scaffold(
      backgroundColor: ssBg,
      body: SafeArea(
        child: Column(
          children: [
            AppHeader(onBack: () => Navigator.pop(context)),
            Expanded(
              child: StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
                stream: userRef.snapshots(),
                builder: (context, snapshot) {
                  final data = snapshot.data?.data();

                  if (snapshot.connectionState == ConnectionState.waiting &&
                      data == null) {
                    return const Center(
                      child: CircularProgressIndicator(color: ssOrange),
                    );
                  }

                  final rawBaseName = data?['baseName']?.toString().trim();
                  final authDisplayName = widget.user.displayName?.trim();
                  final baseName = formatUserDisplayName(
                    rawBaseName != null && rawBaseName.isNotEmpty
                        ? rawBaseName
                        : authDisplayName != null && authDisplayName.isNotEmpty
                        ? authDisplayName
                        : 'Usuario',
                  );
                  final basePhotoUrl = data?['basePhotoUrl'] as String?;
                  final profilePhotoStoragePath =
                      data?['profilePhotoStoragePath']?.toString();

                  if (!nameInitialized &&
                      (data != null || baseName != 'Usuario')) {
                    nameController.text = baseName;
                    nameController.selection = TextSelection.fromPosition(
                      TextPosition(offset: nameController.text.length),
                    );
                    nameInitialized = true;
                  }

                  return ValueListenableBuilder<TextEditingValue>(
                    valueListenable: nameController,
                    builder: (context, value, _) {
                      final newName = value.text.trim();
                      final nameChanged =
                          newName.isNotEmpty && newName != baseName;
                      final photoChanged = selectedPhoto != null;
                      final hasChanges = nameChanged || photoChanged;
                      final canSave = hasChanges &&
                          !saving &&
                          newName.isNotEmpty &&
                          (!photoChanged || selectedPhotoFilterApplied);

                      return ListView(
                        padding: const EdgeInsets.fromLTRB(20, 0, 20, 28),
                        children: [
                          const Text(
                            'Editar perfil',
                            style: TextStyle(
                              color: ssTitle,
                              fontSize: 22,
                              fontWeight: FontWeight.w800,
                            ),
                          ),
                          const SizedBox(height: 16),
                          Padding(
                            padding: const EdgeInsets.fromLTRB(0, 4, 0, 20),
                            child: Column(
                              children: [
                                EditableProfileAvatar(
                                  name: newName.isEmpty ? baseName : newName,
                                  photoUrl: basePhotoUrl,
                                  selectedPhoto: selectedPhoto,
                                  filterApplied: selectedPhotoFilterApplied,
                                  canChangePhoto: esDomingo(),
                                  onTap: saving ? null : _choosePhotoSource,
                                ),
                                const SizedBox(height: 16),
                                Text(
                                  esDomingo()
                                      ? 'Hoy puedes cambiar tu foto de perfil'
                                      : 'La foto de perfil se puede cambiar cada domingo',
                                  textAlign: TextAlign.center,
                                  style: const TextStyle(
                                    color: ssText3,
                                    fontSize: 12,
                                    fontWeight: FontWeight.w600,
                                  ),
                                ),
                              ],
                            ),
                          ),
                          const SizedBox(height: 24),
                          const Text(
                            'NOMBRE',
                            style: TextStyle(
                              color: ssText3,
                              fontSize: 12,
                              fontWeight: FontWeight.w900,
                              letterSpacing: 0.5,
                            ),
                          ),
                          const SizedBox(height: 8),
                          SundayInput(
                            controller: nameController,
                            hintText: 'Tu nombre',
                          ),
                          const SizedBox(height: 6),
                          const Padding(
                            padding: EdgeInsets.only(left: 4),
                            child: Text(
                              'Este es tu nombre en Sunday Selfie',
                              style: TextStyle(
                                color: ssText3,
                                fontSize: 12,
                                fontWeight: FontWeight.w500,
                              ),
                            ),
                          ),
                          const SizedBox(height: 24),
                          SundayButton(
                            text: saved
                                ? 'Guardado'
                                : saving
                                ? 'Guardando...'
                                : 'Guardar cambios',
                            variant: saved
                                ? SundayButtonVariant.secondary
                                : SundayButtonVariant.primary,
                            onPressed: canSave
                                ? () => _saveProfile(
                                      currentName: baseName,
                                      currentPhotoStoragePath:
                                          profilePhotoStoragePath,
                                    )
                                : null,
                          ),
                        ],
                      );
                    },
                  );
                },
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class EditableProfileAvatar extends StatelessWidget {
  final String name;
  final String? photoUrl;
  final XFile? selectedPhoto;
  final bool filterApplied;
  final bool canChangePhoto;
  final VoidCallback? onTap;

  const EditableProfileAvatar({
    super.key,
    required this.name,
    required this.photoUrl,
    required this.selectedPhoto,
    required this.filterApplied,
    required this.canChangePhoto,
    required this.onTap,
  });

  @override
  Widget build(BuildContext context) {
    final hasSelectedPhoto = selectedPhoto != null;
    final hasRemotePhoto = photoUrl != null && photoUrl!.isNotEmpty;

    Widget avatarContent;

    if (hasSelectedPhoto) {
      avatarContent = Image.file(
        File(selectedPhoto!.path),
        width: 96,
        height: 96,
        fit: BoxFit.cover,
        alignment: Alignment.center,
        filterQuality: FilterQuality.high,
      );
    } else if (hasRemotePhoto) {
      avatarContent = Image.network(
        photoUrl!,
        width: 96,
        height: 96,
        fit: BoxFit.cover,
        alignment: Alignment.center,
        filterQuality: FilterQuality.high,
        errorBuilder: (_, __, ___) => Center(
          child: Text(
            initialsFromName(name),
            style: const TextStyle(
              color: Colors.white,
              fontSize: 34,
              fontWeight: FontWeight.w900,
            ),
          ),
        ),
      );
    } else {
      avatarContent = Center(
        child: Text(
          initialsFromName(name),
          style: const TextStyle(
            color: Colors.white,
            fontSize: 34,
            fontWeight: FontWeight.w900,
          ),
        ),
      );
    }

    return GestureDetector(
      onTap: onTap,
      child: Stack(
        clipBehavior: Clip.none,
        children: [
          Container(
            width: 96,
            height: 96,
            decoration: BoxDecoration(
              color: ssOrange,
              shape: BoxShape.circle,
              border: Border.all(color: Colors.white, width: 3),
              boxShadow: [
                BoxShadow(
                  color: Colors.black.withValues(alpha: 0.10),
                  blurRadius: 18,
                  offset: const Offset(0, 6),
                ),
              ],
            ),
            child: ClipOval(
              child: Stack(
                fit: StackFit.expand,
                children: [
                  Container(color: ssOrange, child: avatarContent),
                  if (hasSelectedPhoto && filterApplied)
                    DecoratedBox(
                      decoration: BoxDecoration(
                        color: ssOrange.withValues(alpha: 0.16),
                        backgroundBlendMode: BlendMode.softLight,
                      ),
                    ),
                  if (hasSelectedPhoto && filterApplied)
                    DecoratedBox(
                      decoration: BoxDecoration(
                        gradient: RadialGradient(
                          center: const Alignment(-0.45, -0.55),
                          radius: 1.2,
                          colors: [
                            Colors.white.withValues(alpha: 0.10),
                            Colors.transparent,
                            ssOrangeDark.withValues(alpha: 0.20),
                          ],
                          stops: const [0, 0.58, 1],
                        ),
                      ),
                    ),
                ],
              ),
            ),
          ),
          Positioned(
            right: -1,
            bottom: 2,
            child: Container(
              width: 30,
              height: 30,
              decoration: BoxDecoration(
                color: canChangePhoto ? ssOrange : ssText3,
                shape: BoxShape.circle,
                border: Border.all(color: Colors.white, width: 2.5),
              ),
              child: Icon(
                canChangePhoto
                    ? Icons.edit_rounded
                    : Icons.lock_outline_rounded,
                color: Colors.white,
                size: canChangePhoto ? 17 : 15,
              ),
            ),
          ),
        ],
      ),
    );
  }
}

