class NotificationsSettingsScreen extends StatefulWidget {
  final User user;

  const NotificationsSettingsScreen({super.key, required this.user});

  @override
  State<NotificationsSettingsScreen> createState() =>
      _NotificationsSettingsScreenState();
}

class _NotificationsSettingsScreenState
    extends State<NotificationsSettingsScreen> {
  bool saving = false;

  DocumentReference<Map<String, dynamic>> get userRef => FirebaseFirestore
      .instance
      .collection('users')
      .doc(widget.user.uid);

  Future<void> _setUserNotificationSetting(String key, bool value) async {
    if (saving) return;

    setState(() => saving = true);

    try {
      await userRef.set({
        'notificationSettings': {
          key: value,
          'updatedAt': FieldValue.serverTimestamp(),
        },
        'lastActiveAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));

      if (key == 'globalEnabled') {
        await actualizarEstadoTokensNotificacion(
          user: widget.user,
          enabled: value,
        );

        if (value) {
          await registrarTokenNotificaciones(widget.user);
        }
      }
    } catch (error) {
      if (!mounted) return;
      showSundaySnack(context, 'Error guardando notificaciones: $error');
    } finally {
      if (mounted) setState(() => saving = false);
    }
  }

  Future<void> _setGroupNotificationOverride(
    String groupId,
    String value,
  ) async {
    try {
      await FirebaseFirestore.instance
          .collection('users')
          .doc(widget.user.uid)
          .collection('groups')
          .doc(groupId)
          .update({
            'notificationsOverride': value,
            'notificationsOverrideUpdatedAt': FieldValue.serverTimestamp(),
          });
    } catch (error) {
      if (!mounted) return;
      showSundaySnack(context, 'Error: $error');
    }
  }

  @override
  Widget build(BuildContext context) {
    final groupsRef = FirebaseFirestore.instance
        .collection('users')
        .doc(widget.user.uid)
        .collection('groups')
        .orderBy('joinedAt', descending: true);

    return Scaffold(
      backgroundColor: ssBg,
      body: SafeArea(
        child: Column(
          children: [
            AppHeader(onBack: () => Navigator.pop(context)),
            Expanded(
              child: StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
                stream: userRef.snapshots(),
                builder: (context, userSnapshot) {
                  final userData = userSnapshot.data?.data();
                  final settings = resolvedNotificationSettings(userData);
                  final globalOn = settings['globalEnabled'] ?? true;

                  if (userSnapshot.connectionState == ConnectionState.waiting) {
                    return const Center(
                      child: CircularProgressIndicator(color: ssOrange),
                    );
                  }

                  return ListView(
                    padding: const EdgeInsets.fromLTRB(20, 0, 20, 28),
                    children: [
                      const Text(
                        'Notificaciones',
                        style: TextStyle(
                          color: ssTitle,
                          fontSize: 22,
                          fontWeight: FontWeight.w800,
                        ),
                      ),
                      const SizedBox(height: 16),
                      SettingsSectionCard(
                        children: [
                          SettingsToggleRow(
                            title: 'Notificaciones activadas',
                            subtitle:
                                'Activa o desactiva todas las notificaciones',
                            value: globalOn,
                            onChanged: saving
                                ? null
                                : (value) => _setUserNotificationSetting(
                                      'globalEnabled',
                                      value,
                                    ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 20),
                      const SettingsSectionTitle('TIPOS DE NOTIFICACIÓN'),
                      Opacity(
                        opacity: globalOn ? 1 : 0.4,
                        child: IgnorePointer(
                          ignoring: !globalOn,
                          child: SettingsSectionCard(
                            children: [
                              SettingsToggleRow(
                                title: 'Recordatorio del domingo',
                                subtitle: 'Aviso el domingo para subir tu selfie',
                                value: settings['sundayTimeEnabled'] ?? true,
                                onChanged: saving
                                    ? null
                                    : (value) => _setUserNotificationSetting(
                                          'sundayTimeEnabled',
                                          value,
                                        ),
                              ),
                              const SettingsDivider(),
                              SettingsToggleRow(
                                title: 'Nuevos selfies',
                                subtitle:
                                    'Cuando alguien publica una selfie en tus grupos',
                                value: settings['newSelfiesEnabled'] ?? true,
                                onChanged: saving
                                    ? null
                                    : (value) => _setUserNotificationSetting(
                                          'newSelfiesEnabled',
                                          value,
                                        ),
                              ),
                              const SettingsDivider(),
                              SettingsToggleRow(
                                title: 'Recordatorios de amigos',
                                subtitle:
                                    'Cuando un amigo te envía un zumbido para recordarte subir tu selfie',
                                value: settings['friendRemindersEnabled'] ?? true,
                                onChanged: saving
                                    ? null
                                    : (value) => _setUserNotificationSetting(
                                          'friendRemindersEnabled',
                                          value,
                                        ),
                              ),
                              const SettingsDivider(),
                              SettingsToggleRow(
                                title: 'Nuevas reacciones',
                                subtitle: 'Cuando alguien reacciona a tu selfie',
                                value: settings['reactionsEnabled'] ?? true,
                                onChanged: saving
                                    ? null
                                    : (value) => _setUserNotificationSetting(
                                          'reactionsEnabled',
                                          value,
                                        ),
                              ),
                              const SettingsDivider(),
                              SettingsToggleRow(
                                title: 'Nuevos miembros',
                                subtitle: 'Cuando alguien se une a tu grupo',
                                value: settings['newMembersEnabled'] ?? true,
                                onChanged: saving
                                    ? null
                                    : (value) => _setUserNotificationSetting(
                                          'newMembersEnabled',
                                          value,
                                        ),
                              ),
                              const SettingsDivider(),
                              SettingsToggleRow(
                                title: 'Resumen semanal',
                                subtitle: 'Cada lunes con las fotos de la semana',
                                value: settings['weeklySummaryEnabled'] ?? false,
                                onChanged: saving
                                    ? null
                                    : (value) => _setUserNotificationSetting(
                                          'weeklySummaryEnabled',
                                          value,
                                        ),
                              ),
                            ],
                          ),
                        ),
                      ),
                      const SizedBox(height: 20),
                      const SettingsSectionTitle('POR GRUPO'),
                      Opacity(
                        opacity: globalOn ? 1 : 0.4,
                        child: IgnorePointer(
                          ignoring: !globalOn,
                          child: StreamBuilder<
                              QuerySnapshot<Map<String, dynamic>>>(
                            stream: groupsRef.snapshots(),
                            builder: (context, snapshot) {
                              final groups = snapshot.data?.docs ?? [];
                              if (groups.isEmpty) {
                                return const SettingsSectionCard(
                                  children: [
                                    SettingsInfoRow(
                                      title: 'Sin grupos todavía',
                                      subtitle:
                                          'Cuando tengas grupos, podrás ajustar las notificaciones de cada uno.',
                                    ),
                                  ],
                                );
                              }

                              return SettingsSectionCard(
                                children: List.generate(groups.length * 2 - 1,
                                    (index) {
                                  if (index.isOdd) return const SettingsDivider();
                                  final doc = groups[index ~/ 2];
                                  final data = doc.data();
                                  final groupId = (data['groupId'] ?? doc.id).toString();
                                  final groupName =
                                      data['displayNameSnapshot'] ?? 'Grupo';
                                  final rawGroupPhotoUrl = data['groupPhotoUrlSnapshot'];
                                  final groupPhotoUrl = rawGroupPhotoUrl is String
                                      ? rawGroupPhotoUrl
                                      : null;
                                  final value =
                                      data['notificationsOverride'] ?? 'on';
                                  return GroupNotificationRow(
                                    groupId: groupId,
                                    groupName: groupName,
                                    groupPhotoUrl: groupPhotoUrl,
                                    value: value,
                                    enabled: globalOn && !saving,
                                    onChanged: (newValue) {
                                      _setGroupNotificationOverride(
                                        groupId,
                                        newValue,
                                      );
                                    },
                                  );
                                }),
                              );
                            },
                          ),
                        ),
                      ),
                      const SizedBox(height: 20),
                      const SettingsSectionTitle('DISPOSITIVO'),
                      Opacity(
                        opacity: globalOn ? 1 : 0.4,
                        child: IgnorePointer(
                          ignoring: !globalOn,
                          child: SettingsSectionCard(
                            children: [
                              SettingsToggleRow(
                                title: 'Sonido',
                                subtitle:
                                    'Permite que las notificaciones suenen si el sistema lo permite',
                                value: settings['soundEnabled'] ?? true,
                                onChanged: saving
                                    ? null
                                    : (value) => _setUserNotificationSetting(
                                          'soundEnabled',
                                          value,
                                        ),
                              ),
                              const SettingsDivider(),
                              SettingsToggleRow(
                                title: 'Vibración',
                                subtitle:
                                    'Permite vibración en avisos compatibles',
                                value: settings['vibrationEnabled'] ?? true,
                                onChanged: saving
                                    ? null
                                    : (value) => _setUserNotificationSetting(
                                          'vibrationEnabled',
                                          value,
                                        ),
                              ),
                            ],
                          ),
                        ),
                      ),
                      const SizedBox(height: 14),
                      const SettingsInfoRow(
                        title: 'Guardado automático',
                        subtitle:
                            'Estos ajustes se guardan en tu perfil y quedan preparados para que las Cloud Functions filtren los envíos.',
                      ),
                    ],
                  );
                },
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class AppSettingsScreen extends StatefulWidget {
  final User user;

  const AppSettingsScreen({super.key, required this.user});

  @override
  State<AppSettingsScreen> createState() => _AppSettingsScreenState();
}

class _AppSettingsScreenState extends State<AppSettingsScreen> {
  bool autoDownload = true;
  bool clearDone = false;

  Future<void> _confirmClearCache() async {
    final confirmed = await showModalBottomSheet<bool>(
      context: context,
      backgroundColor: Colors.white,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
      ),
      builder: (sheetContext) {
        return SafeArea(
          top: false,
          child: Padding(
            padding: const EdgeInsets.fromLTRB(24, 20, 24, 36),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Center(
                  child: Container(
                    width: 36,
                    height: 4,
                    decoration: BoxDecoration(
                      color: ssBorder,
                      borderRadius: BorderRadius.circular(4),
                    ),
                  ),
                ),
                const SizedBox(height: 20),
                const Text(
                  '¿Borrar el contenido descargado?',
                  style: TextStyle(
                    color: ssText,
                    fontSize: 17,
                    fontWeight: FontWeight.w900,
                  ),
                ),
                const SizedBox(height: 8),
                const Text(
                  'No afecta al contenido en la nube. Podrás volver a descargarlo cuando quieras.',
                  style: TextStyle(color: ssText2, fontSize: 14, height: 1.35),
                ),
                const SizedBox(height: 20),
                SundayButton(
                  text: 'Borrar caché',
                  onPressed: () => Navigator.pop(sheetContext, true),
                ),
                const SizedBox(height: 10),
                SundayButton(
                  text: 'Cancelar',
                  variant: SundayButtonVariant.ghost,
                  onPressed: () => Navigator.pop(sheetContext, false),
                ),
              ],
            ),
          ),
        );
      },
    );

    if (confirmed == true) {
      setState(() => clearDone = true);
      await Future<void>.delayed(const Duration(seconds: 3));
      if (mounted) setState(() => clearDone = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: ssBg,
      body: SafeArea(
        child: Column(
          children: [
            AppHeader(onBack: () => Navigator.pop(context)),
            Expanded(
              child: ListView(
                padding: const EdgeInsets.fromLTRB(20, 0, 20, 28),
                children: [
                  const Text(
                    'Ajustes',
                    style: TextStyle(
                      color: ssText,
                      fontSize: 22,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                  const SizedBox(height: 20),
                  const SettingsSectionTitle('ALMACENAMIENTO'),
                  SettingsSectionCard(
                    children: [
                      SettingsToggleRow(
                        title: 'Descarga automática',
                        subtitle:
                            'Solo aplica a selfies nuevos desde que te unes',
                        value: autoDownload,
                        onChanged: (value) =>
                            setState(() => autoDownload = value),
                      ),
                      const SettingsDivider(),
                      SettingsNavigationRow(
                        title: clearDone
                            ? '✅ Caché borrada'
                            : 'Borrar caché local',
                        subtitle: 'Libera espacio descargado localmente',
                        titleColor: clearDone
                            ? const Color(0xFF4CAF50)
                            : ssText,
                        showChevron: !clearDone,
                        onTap: clearDone ? null : _confirmClearCache,
                      ),
                    ],
                  ),
                  const SizedBox(height: 6),
                  const Padding(
                    padding: EdgeInsets.only(left: 4),
                    child: Text(
                      'Las fotos originales permanecen en la nube',
                      style: TextStyle(
                        color: ssText3,
                        fontSize: 12,
                        fontWeight: FontWeight.w500,
                      ),
                    ),
                  ),
                  const SizedBox(height: 24),
                  const SettingsSectionTitle('LEGAL'),
                  SettingsSectionCard(
                    children: [
                      SettingsNavigationRow(
                        title: 'Política de privacidad',
                        onTap: () => showSundaySnack(
                          context,
                          'Pendiente de añadir enlace legal',
                        ),
                      ),
                      const SettingsDivider(),
                      SettingsNavigationRow(
                        title: 'Términos de uso',
                        onTap: () => showSundaySnack(
                          context,
                          'Pendiente de añadir enlace legal',
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 24),
                  const Text(
                    'Sunday Selfie v1.0 (beta)',
                    textAlign: TextAlign.center,
                    style: TextStyle(
                      color: ssText3,
                      fontSize: 13,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

