class GroupNotificationRow extends StatelessWidget {
  final String groupId;
  final String groupName;
  final String? groupPhotoUrl;
  final String value;
  final bool enabled;
  final ValueChanged<String> onChanged;

  const GroupNotificationRow({
    super.key,
    required this.groupId,
    required this.groupName,
    required this.groupPhotoUrl,
    required this.value,
    required this.enabled,
    required this.onChanged,
  });

  @override
  Widget build(BuildContext context) {
    final normalized = value == 'off' ? 'off' : 'on';

    return StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
      stream: FirebaseFirestore.instance.collection('groups').doc(groupId).snapshots(),
      builder: (context, snapshot) {
        final groupData = snapshot.data?.data();
        final resolvedName = (groupData?['name'] ?? groupName).toString();
        final rawResolvedPhotoUrl = groupData?['photoUrl'];
        final resolvedPhotoUrl = rawResolvedPhotoUrl is String &&
                rawResolvedPhotoUrl.trim().isNotEmpty
            ? rawResolvedPhotoUrl.trim()
            : groupPhotoUrl;

        return Padding(
          padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
          child: Row(
            children: [
              GroupIconSmall(
                name: resolvedName,
                photoUrl: resolvedPhotoUrl,
              ),
              const SizedBox(width: 12),
              Expanded(
                child: Text(
                  formatGroupDisplayName(resolvedName),
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(
                    color: ssText,
                    fontSize: 14,
                    fontWeight: FontWeight.w700,
                  ),
                ),
              ),
              Container(
                height: 34,
                padding: const EdgeInsets.symmetric(horizontal: 8),
                decoration: BoxDecoration(
                  color: ssBg,
                  borderRadius: BorderRadius.circular(8),
                  border: Border.all(color: ssBorder),
                ),
                child: DropdownButtonHideUnderline(
                  child: DropdownButton<String>(
                    value: normalized,
                    iconSize: 18,
                    borderRadius: BorderRadius.circular(12),
                    style: const TextStyle(
                      color: ssText2,
                      fontSize: 12,
                      fontWeight: FontWeight.w700,
                    ),
                    items: const [
                      DropdownMenuItem(value: 'on', child: Text('Activadas')),
                      DropdownMenuItem(value: 'off', child: Text('Desactivadas')),
                    ],
                    onChanged: enabled
                        ? (newValue) {
                            if (newValue != null) onChanged(newValue);
                          }
                        : null,
                  ),
                ),
              ),
            ],
          ),
        );
      },
    );
  }
}

class GroupIconSmall extends StatelessWidget {
  final String name;
  final String? photoUrl;

  const GroupIconSmall({
    super.key,
    required this.name,
    required this.photoUrl,
  });

  bool get hasPhoto => photoUrl != null && photoUrl!.trim().isNotEmpty;

  @override
  Widget build(BuildContext context) {
    final emoji = extractLastEmoji(name);

    return Container(
      width: 36,
      height: 36,
      decoration: BoxDecoration(
        color: ssOrangeLight,
        borderRadius: BorderRadius.circular(10),
        border: Border.all(color: ssBorder),
      ),
      clipBehavior: Clip.antiAlias,
      alignment: Alignment.center,
      child: hasPhoto
          ? Image.network(
              photoUrl!,
              width: 36,
              height: 36,
              fit: BoxFit.cover,
              alignment: Alignment.center,
              filterQuality: FilterQuality.high,
              errorBuilder: (_, __, ___) => Center(
                child: Text(
                  emoji ?? initialsFromName(name),
                  style: const TextStyle(
                    color: ssOrangeDark,
                    fontSize: 16,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ),
            )
          : Text(
              emoji ?? initialsFromName(name),
              style: const TextStyle(
                color: ssOrangeDark,
                fontSize: 16,
                fontWeight: FontWeight.w900,
              ),
            ),
    );
  }
}

class SundaySwitch extends StatelessWidget {
  final bool value;
  final ValueChanged<bool>? onChanged;

  const SundaySwitch({super.key, required this.value, required this.onChanged});

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: onChanged == null ? null : () => onChanged!(!value),
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 180),
        width: 46,
        height: 26,
        decoration: BoxDecoration(
          color: value ? ssOrange : ssBorder,
