Future<int> countUserSelfies(
  String userUid,
  List<QueryDocumentSnapshot<Map<String, dynamic>>> groupDocs,
) async {
  final firestore = FirebaseFirestore.instance;
  var count = 0;

  for (final groupDoc in groupDocs) {
    final data = groupDoc.data();
    final groupId = data['groupId'] ?? groupDoc.id;
    try {
      final weeks = await firestore
          .collection('groups')
          .doc(groupId)
          .collection('weeks')
          .limit(50)
          .get();
      for (final week in weeks.docs) {
        final post = await week.reference
            .collection('posts')
            .doc(userUid)
            .get();
        if (post.exists) count += 1;
      }
    } catch (_) {
      // Ignoramos grupos antiguos o sin permisos para no bloquear la pantalla.
    }
  }

  return count;
}

int activeWeeksFromGroups(
  List<QueryDocumentSnapshot<Map<String, dynamic>>> groupDocs,
) {
  if (groupDocs.isEmpty) return 0;

  final joinedDates = groupDocs
      .map((doc) => timestampToDate(doc.data()['joinedAt']))
      .whereType<DateTime>()
      .toList();

  if (joinedDates.isEmpty) return 0;

  joinedDates.sort();
  final first = joinedDates.first;
  final now = DateTime.now();
  if (first.isAfter(now)) return 0;

  final firstDay = DateTime(first.year, first.month, first.day);
  final firstSunday = firstDay.add(
    Duration(
      days: first.weekday == DateTime.sunday
          ? 7
          : DateTime.sunday - first.weekday,
    ),
  );

  if (now.isBefore(firstSunday)) return 0;

  return (now.difference(firstSunday).inDays ~/ 7 + 1).clamp(1, 9999).toInt();
}

String monthName(int month) {
  const months = [
    'enero',
    'febrero',
    'marzo',
    'abril',
    'mayo',
    'junio',
    'julio',
    'agosto',
    'septiembre',
    'octubre',
    'noviembre',
    'diciembre',
  ];
  if (month < 1 || month > 12) return '';
  return months[month - 1];
}

class CameraCaptureScreen extends StatefulWidget {
  final String? groupName;

  const CameraCaptureScreen({super.key, this.groupName});

  @override
  State<CameraCaptureScreen> createState() => _CameraCaptureScreenState();
}

class _CameraCaptureScreenState extends State<CameraCaptureScreen> {
  CameraController? controller;
  List<CameraDescription> cameras = [];
  int cameraIndex = 0;
  bool loading = true;
  bool taking = false;
  bool switching = false;
  String? error;

  @override
  void initState() {
    super.initState();
    _initCamera();
  }

  Future<void> _initCamera() async {
    try {
      final available = await availableCameras();
      if (available.isEmpty) {
        setState(() {
          error =
              'No se ha encontrado cámara disponible. En el simulador iOS esto es normal.';
          loading = false;
        });
        return;
      }

      final frontIndex = available.indexWhere(
        (camera) => camera.lensDirection == CameraLensDirection.front,
      );

      cameras = available;
      cameraIndex = frontIndex >= 0 ? frontIndex : 0;
      await _startController(cameras[cameraIndex]);
    } catch (e) {
      if (!mounted) return;
      setState(() {
        error = 'Error iniciando cámara: $e';
        loading = false;
      });
    }
  }

  Future<void> _startController(CameraDescription camera) async {
    final oldController = controller;
    controller = null;
    await oldController?.dispose();

    final camController = CameraController(
      camera,
      ResolutionPreset.medium,
      enableAudio: false,
      imageFormatGroup: ImageFormatGroup.jpeg,
    );

    await camController.initialize();

    if (!mounted) {
      await camController.dispose();
      return;
    }

    setState(() {
      controller = camController;
      loading = false;
      switching = false;
      error = null;
    });
  }

  @override
  void dispose() {
    controller?.dispose();
    super.dispose();
  }

  Future<void> _switchCamera() async {
    if (cameras.length < 2 || switching || taking) return;

    setState(() => switching = true);
    try {
      cameraIndex = (cameraIndex + 1) % cameras.length;
      await _startController(cameras[cameraIndex]);
    } catch (e) {
      if (!mounted) return;
      setState(() {
        error = 'Error cambiando cámara: $e';
        switching = false;
      });
    }
  }

  Future<void> _takePicture() async {
    final cam = controller;
    if (cam == null || !cam.value.isInitialized || taking || switching) return;

    setState(() => taking = true);
    try {
      final picture = await cam.takePicture();
      if (!mounted) return;
      Navigator.pop(context, picture);
    } catch (e) {
      if (!mounted) return;
      showSundaySnack(context, 'Error haciendo foto: $e');
      setState(() => taking = false);
    }
  }

  Widget _buildPreview() {
    final cam = controller;

    if (loading || switching) {
      return const Center(child: CircularProgressIndicator(color: ssOrange));
    }

    if (error != null) {
      return Center(
        child: Padding(
          padding: const EdgeInsets.all(28),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Container(
                width: 86,
                height: 86,
                decoration: const BoxDecoration(
                  color: ssOrange,
                  shape: BoxShape.circle,
                ),
                child: const Icon(
                  Icons.no_photography_rounded,
                  color: Colors.white,
                  size: 40,
                ),
              ),
              const SizedBox(height: 22),
              Text(
                error!,
                textAlign: TextAlign.center,
                style: const TextStyle(
                  color: Colors.white,
                  fontSize: 16,
                  height: 1.45,
                  fontWeight: FontWeight.w700,
                ),
              ),
              const SizedBox(height: 22),
              GestureDetector(
                onTap: () => Navigator.pop(context),
                child: Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 20,
                    vertical: 12,
                  ),
                  decoration: BoxDecoration(
                    color: Colors.white,
                    borderRadius: BorderRadius.circular(18),
                  ),
                  child: const Text(
                    'Volver',
                    style: TextStyle(
                      color: ssText,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                ),
              ),
            ],
          ),
        ),
      );
    }

    if (cam == null || !cam.value.isInitialized) {
      return const Center(child: CircularProgressIndicator(color: ssOrange));
    }

    return Center(
      child: SizedBox.expand(
        child: FittedBox(
          fit: BoxFit.cover,
          child: SizedBox(
            width: cam.value.previewSize?.height ?? 1,
            height: cam.value.previewSize?.width ?? 1,
            child: CameraPreview(cam),
          ),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final bottomPadding = MediaQuery.of(context).padding.bottom;
    final cameraReady =
        error == null &&
        !loading &&
        !switching &&
        controller != null &&
        controller!.value.isInitialized;

    return Scaffold(
      backgroundColor: Colors.black,
      body: Stack(
        children: [
          Positioned.fill(child: _buildPreview()),
          Positioned.fill(
            child: IgnorePointer(
              child: DecoratedBox(
                decoration: BoxDecoration(
                  gradient: LinearGradient(
                    begin: Alignment.topCenter,
                    end: Alignment.bottomCenter,
                    colors: [
                      Colors.black.withOpacity(0.70),
                      Colors.transparent,
                      Colors.transparent,
                      Colors.black.withOpacity(0.80),
                    ],
                    stops: const [0, 0.22, 0.68, 1],
                  ),
                ),
              ),
            ),
          ),
          Positioned(
            left: 18,
            right: 18,
            top: 0,
            child: SafeArea(
              bottom: false,
              child: Padding(
                padding: const EdgeInsets.only(top: 10),
                child: Row(
                  children: [
                    CircleIconButton(
                      icon: Icons.close_rounded,
                      dark: true,
                      onTap: () => Navigator.pop(context),
                    ),
                    const SizedBox(width: 14),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          const Text(
                            'Sunday Selfie',
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: TextStyle(
                              color: Colors.white,
                              fontSize: 20,
