                                fontWeight: FontWeight.w700,
                              ),
                            ),
                          ],
                        ],
                      ),
                    ),
                    const SizedBox(width: 14),
                    Opacity(
                      opacity: cameras.length >= 2 && cameraReady ? 1 : 0.35,
                      child: CircleIconButton(
