                  ),
                  Positioned(
                    left: 20,
                    bottom: compact ? 17 : 18,
                    width: leftBlockWidth,
                    child: Text(
                      leftText,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: TextStyle(
                        color: Colors.white.withValues(alpha: 0.94),
                        fontSize: compact ? 12.5 : 13.5,
                        fontWeight: FontWeight.w600,
                        height: 1,
                      ),
                    ),
                  ),
                  if (!isSunday)
                    Positioned(
                      right: 22,
                      bottom: compact ? 17 : 18,
                      width: rightBlockWidth,
                      child: FittedBox(
                        fit: BoxFit.scaleDown,
                        alignment: Alignment.centerRight,
                        child: Text(
                          rightText,
                          maxLines: 1,
                          textAlign: TextAlign.right,
                          style: TextStyle(
                            color: Colors.white.withValues(alpha: 0.92),
                            fontSize: compact ? 12 : 13.2,
                            fontWeight: FontWeight.w600,
                            height: 1,
                          ),
                        ),
                      ),
                    ),
                ],
              ),
            );
          },
        );
      },
    );
  }
}

class SundayCard extends StatelessWidget {
  final Widget child;
  final EdgeInsetsGeometry? margin;
  final EdgeInsetsGeometry? padding;
  final VoidCallback? onTap;

  const SundayCard({
    super.key,
    required this.child,
    this.margin,
    this.padding,
    this.onTap,
  });

  @override
  Widget build(BuildContext context) {
    final card = Container(
      margin: margin,
      padding: padding ?? const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: ssSurface,
        borderRadius: BorderRadius.circular(24),
        border: Border.all(color: ssBorder),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withValues(alpha: 0.04),
            blurRadius: 14,
            offset: const Offset(0, 4),
          ),
        ],
      ),
      child: child,
    );

    if (onTap == null) return card;

    return InkWell(
      onTap: onTap,
      borderRadius: BorderRadius.circular(24),
      child: card,
    );
  }
}

class GroupIcon extends StatelessWidget {
  final String name;
  final String? photoUrl;
  final String? emoji;
  final Object? colorValue;
  final double size;

  const GroupIcon({
    super.key,
    required this.name,
    this.photoUrl,
    this.emoji,
    this.colorValue,
    this.size = 52,
  });

  bool get hasPhoto => photoUrl != null && photoUrl!.trim().isNotEmpty;

  @override
  Widget build(BuildContext context) {
    final resolvedColor = groupColorFromValue(colorValue);
    final resolvedEmoji = emoji?.trim().isNotEmpty == true
        ? emoji!.trim()
        : extractLastEmoji(name) ?? fallbackGroupEmoji(name);
    final radius = size * 0.34;

    return Container(
      width: size,
      height: size,
      alignment: Alignment.center,
      decoration: BoxDecoration(
        color: hasPhoto ? Colors.white : resolvedColor.withValues(alpha: 0.16),
        borderRadius: BorderRadius.circular(radius),
        border: Border.all(
          color: hasPhoto ? ssBorder : resolvedColor.withValues(alpha: 0.28),
          width: 2,
        ),
      ),
      clipBehavior: Clip.antiAlias,
      child: hasPhoto
          ? Image.network(
              photoUrl!.trim(),
              width: size,
              height: size,
              fit: BoxFit.cover,
              alignment: Alignment.center,
              filterQuality: FilterQuality.high,
              errorBuilder: (_, __, ___) => _GroupIconFallback(
                name: name,
                emoji: resolvedEmoji,
                color: resolvedColor,
                size: size,
              ),
            )
          : _GroupIconFallback(
              name: name,
              emoji: resolvedEmoji,
              color: resolvedColor,
              size: size,
            ),
    );
  }
}

class _GroupIconFallback extends StatelessWidget {
  final String name;
  final String? emoji;
  final Color color;
  final double size;

  const _GroupIconFallback({
    required this.name,
    required this.emoji,
    required this.color,
    required this.size,
  });

  @override
  Widget build(BuildContext context) {
    final hasEmoji = emoji != null && emoji!.trim().isNotEmpty;

    return Center(
      child: Text(
        hasEmoji ? emoji! : initialsFromName(name),
        style: TextStyle(
          color: hasEmoji ? ssText : color,
          fontSize: hasEmoji ? size * 0.42 : size * 0.34,
          fontWeight: FontWeight.w900,
          height: 1,
        ),
      ),
    );
  }
}


class MiniProfileAvatar extends StatelessWidget {
