class GroupMembersAvatarStrip extends StatelessWidget {
  final String groupId;
  final int memberCount;

  const GroupMembersAvatarStrip({
    super.key,
    required this.groupId,
    required this.memberCount,
  });

  @override
  Widget build(BuildContext context) {
    final membersRef = FirebaseFirestore.instance
        .collection('groups')
        .doc(groupId)
        .collection('members')
        .orderBy('joinedAt')
        .limit(4);

    return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
      stream: membersRef.snapshots(),
      builder: (context, snapshot) {
        final members = snapshot.data?.docs ?? [];
        final shown = members.length;
        final remaining = (memberCount - shown).clamp(0, 999);

        if (snapshot.connectionState == ConnectionState.waiting && members.isEmpty) {
          return const SizedBox(height: 30);
        }

        return Row(
          children: [
            ...members.map((member) {
              final data = member.data();
              final name = formatUserDisplayName(data['effectiveName'] ?? 'Usuario');
              final rawPhotoUrl = data['effectivePhotoUrl'];
              final photoUrl = rawPhotoUrl is String ? rawPhotoUrl : null;
              return Padding(
                padding: const EdgeInsets.only(right: 5),
                child: ResolvedMemberMiniAvatar(
                  uid: member.id,
                  name: name,
                  photoUrl: photoUrl,
                ),
              );
            }),
            if (remaining > 0)
              MiniAvatar(
                text: '+$remaining',
                bg: ssSeparator,
                fg: ssText3,
              ),
          ],
        );
      },
    );
  }
}

class ResolvedMemberMiniAvatar extends StatelessWidget {
  final String uid;
  final String name;
  final String? photoUrl;

  const ResolvedMemberMiniAvatar({
    super.key,
    required this.uid,
    required this.name,
    required this.photoUrl,
  });

  bool get hasMemberPhoto => photoUrl != null && photoUrl!.trim().isNotEmpty;

  @override
  Widget build(BuildContext context) {
    if (hasMemberPhoto) {
      return MiniProfileAvatar(name: name, photoUrl: photoUrl, size: 30);
    }

    return StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
      stream: FirebaseFirestore.instance.collection('users').doc(uid).snapshots(),
      builder: (context, snapshot) {
        final userData = snapshot.data?.data();
        final rawUserPhotoUrl = userData?['basePhotoUrl'];
        final resolvedPhotoUrl = rawUserPhotoUrl is String ? rawUserPhotoUrl : null;
        final rawUserName = userData?['baseName'];
        final resolvedName = rawUserName is String && rawUserName.trim().isNotEmpty
            ? rawUserName.trim()
            : name;

        return MiniProfileAvatar(
          name: resolvedName,
          photoUrl: resolvedPhotoUrl,
          size: 30,
        );
      },
    );
  }
}


class GroupStreakMedal extends StatelessWidget {
  final String groupId;
  final String uid;

  const GroupStreakMedal({
    super.key,
    required this.groupId,
    required this.uid,
  });

  void _openRanking(BuildContext context, int medalCount) {
    showModalBottomSheet(
      context: context,
      backgroundColor: Colors.transparent,
      isScrollControlled: true,
      builder: (_) => StreakRankingSheet(
        groupId: groupId,
        uid: uid,
        currentStreak: medalCount,
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<int>(
      future: calcularRachaPublicacionUsuarioEnGrupo(groupId: groupId, uid: uid),
      builder: (context, snapshot) {
        final medalCount = snapshot.data ?? 0;

        if (medalCount <= 0) {
          return const SizedBox.shrink();
        }

        return GestureDetector(
          onTap: () => _openRanking(context, medalCount),
          child: Container(
            width: 34,
            height: 34,
            padding: const EdgeInsets.all(1.2),
            decoration: BoxDecoration(
              color: ssBg,
              shape: BoxShape.circle,
              border: Border.all(color: ssOrangeMid, width: 1.4),
            ),
            child: Container(
              alignment: Alignment.center,
              decoration: const BoxDecoration(
                color: ssOrange,
                shape: BoxShape.circle,
              ),
              child: Text(
                '$medalCount',
                textAlign: TextAlign.center,
                style: TextStyle(
                  color: Colors.white,
                  fontSize: medalCount > 99 ? 11 : 16,
                  fontWeight: FontWeight.w900,
                  height: 1,
                  fontFeatures: const [FontFeature.tabularFigures()],
                ),
              ),
            ),
          ),
        );
      },
    );
  }
}

class StreakRankingSheet extends StatelessWidget {
  final String groupId;
  final String uid;
  final int currentStreak;

  const StreakRankingSheet({
    super.key,
    required this.groupId,
    required this.uid,
    required this.currentStreak,
  });

  @override
  Widget build(BuildContext context) {
    return SafeArea(
      top: false,
      child: Container(
        constraints: BoxConstraints(
          maxHeight: MediaQuery.sizeOf(context).height * 0.78,
        ),
        padding: const EdgeInsets.fromLTRB(20, 12, 20, 24),
        decoration: const BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.vertical(top: Radius.circular(28)),
        ),
        child: FutureBuilder<List<StreakRankingEntry>>(
          future: calcularRankingRachasGrupo(groupId: groupId, currentUid: uid),
          builder: (context, snapshot) {
            final ranking = snapshot.data ?? [];
            final myPosition = ranking.indexWhere((entry) => entry.uid == uid) + 1;
            final leader = ranking.isNotEmpty ? ranking.first : null;
            final inFront = leader?.uid == uid;

            return Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Container(
                  width: 38,
                  height: 4,
                  margin: const EdgeInsets.only(bottom: 18),
                  decoration: BoxDecoration(
                    color: ssBorder,
                    borderRadius: BorderRadius.circular(999),
                  ),
                ),
                Container(
                  width: 54,
                  height: 54,
                  alignment: Alignment.center,
                  decoration: const BoxDecoration(
                    color: ssOrange,
                    shape: BoxShape.circle,
                  ),
                  child: Text(
                    '$currentStreak',
                    style: const TextStyle(
                      color: Colors.white,
                      fontSize: 24,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                ),
                const SizedBox(height: 14),
                Text(
                  currentStreak == 1
                      ? 'Llevas 1 semana seguida publicando.'
                      : 'Llevas $currentStreak semanas seguidas publicando.',
                  textAlign: TextAlign.center,
                  style: const TextStyle(
                    color: ssTitle,
                    fontSize: 19,
                    fontWeight: FontWeight.w900,
                  ),
                ),
                const SizedBox(height: 6),
                Text(
                  inFront
                      ? 'Vas en cabeza en tu grupo.'
                      : myPosition > 0
                          ? 'Estás en la posición $myPosition del ranking.'
                          : 'Sigue publicando para entrar en el ranking.',
                  textAlign: TextAlign.center,
                  style: const TextStyle(
                    color: ssText2,
                    fontSize: 13,
                    fontWeight: FontWeight.w600,
                    height: 1.35,
                  ),
                ),
                const SizedBox(height: 18),
                if (snapshot.connectionState == ConnectionState.waiting)
                  const Padding(
                    padding: EdgeInsets.symmetric(vertical: 24),
                    child: CircularProgressIndicator(color: ssOrange),
                  )
                else
                  Flexible(
                    child: ListView.separated(
                      shrinkWrap: true,
                      itemCount: ranking.length,
                      separatorBuilder: (_, __) =>
                          const Divider(height: 1, color: ssSeparator),
                      itemBuilder: (context, index) {
                        final entry = ranking[index];
                        return Padding(
                          padding: const EdgeInsets.symmetric(vertical: 10),
                          child: Row(
                            children: [
                              SizedBox(
                                width: 26,
                                child: Text(
                                  '${index + 1}',
                                  style: const TextStyle(
                                    color: ssText3,
                                    fontSize: 14,
                                    fontWeight: FontWeight.w900,
                                  ),
                                ),
                              ),
                              MiniProfileAvatar(
                                name: entry.name,
                                photoUrl: entry.photoUrl,
                                size: 36,
                                borderColor: ssBg,
                              ),
                              const SizedBox(width: 10),
                              Expanded(
                                child: Text(
                                  entry.isCurrentUser
                                      ? '${entry.name} · tú'
                                      : entry.name,
                                  maxLines: 1,
                                  overflow: TextOverflow.ellipsis,
                                  style: const TextStyle(
                                    color: ssTitle,
                                    fontSize: 14,
                                    fontWeight: FontWeight.w800,
                                  ),
                                ),
                              ),
                              Text(
                                '${entry.streak}',
                                style: const TextStyle(
                                  color: ssOrangeDark,
                                  fontSize: 15,
                                  fontWeight: FontWeight.w900,
                                  fontFeatures: [FontFeature.tabularFigures()],
                                ),
                              ),
                            ],
                          ),
                        );
                      },
                    ),
                  ),
              ],
            );
          },
        ),
      ),
    );
  }
}

